import React, { createContext, useContext, useState, useEffect, useRef } from 'react';
import { sfx } from '../utils/SoundManager';

// --- CONTEXT ---
interface InteractionContextType {
    setHoveredItem: (name: string | null) => void;
}

const InteractionContext = createContext<InteractionContextType>({
    setHoveredItem: () => {},
});

export const useInteraction = () => useContext(InteractionContext);

// --- VISUAL UI COMPONENT ---
export const InteractionUI: React.FC = () => {
    const [tooltipData, setTooltipData] = useState<{ name: string; x: number; y: number; visible: boolean }>({ 
        name: '', x: 0, y: 0, visible: false 
    });
    const [toast, setToast] = useState<{ msg: string; visible: boolean }>({ msg: '', visible: false });

    // Internal state tracking for logic outside React render cycle
    const hoveredNameRef = useRef<string | null>(null);
    const mousePosRef = useRef({ x: 0, y: 0 });

    useEffect(() => {
        const handleMouseMove = (e: MouseEvent) => {
            mousePosRef.current = { x: e.clientX, y: e.clientY };

            // Actualizar posición del tooltip si es visible
            if (e.ctrlKey && hoveredNameRef.current) {
                setTooltipData(prev => ({
                    ...prev,
                    x: e.clientX,
                    y: e.clientY,
                    visible: true,
                    name: hoveredNameRef.current || ''
                }));
            } else {
                setTooltipData(prev => ({ ...prev, visible: false }));
            }
        };

        const handleKeyDown = (e: KeyboardEvent) => {
            // Lógica 1: CONTROL (Mostrar Nombre)
            if (e.key === 'Control') {
                if (hoveredNameRef.current) {
                    setTooltipData({
                        name: hoveredNameRef.current,
                        x: mousePosRef.current.x,
                        y: mousePosRef.current.y,
                        visible: true
                    });
                    // Pequeño sonido técnico al activar la vista
                    // sfx.play('HOVER'); 
                }
            }

            // Lógica 2: SHIFT (Copiar)
            if (e.key === 'Shift') {
                if (hoveredNameRef.current) {
                    // Copiar al portapapeles
                    navigator.clipboard.writeText(hoveredNameRef.current).then(() => {
                        // Feedback Sonoro
                        sfx.play('CLICK');

                        // Feedback Visual (Toast)
                        setToast({ msg: `DATA ACQUIRED: ${hoveredNameRef.current}`, visible: true });
                        setTimeout(() => setToast(prev => ({ ...prev, visible: false })), 2000);
                    }).catch(err => console.error('Clipboard failed', err));
                }
            }
        };

        const handleKeyUp = (e: KeyboardEvent) => {
            if (e.key === 'Control') {
                setTooltipData(prev => ({ ...prev, visible: false }));
            }
        };

        // Custom event listener helper for GameImage to communicate without re-renders
        const handleHoverChange = (e: CustomEvent) => {
            hoveredNameRef.current = e.detail;
            if (!e.detail) {
                setTooltipData(prev => ({ ...prev, visible: false }));
            } else if (e.detail && tooltipData.visible) {
                // Update name immediately if dragging/moving between images while holding Ctrl
                setTooltipData(prev => ({ ...prev, name: e.detail }));
            }
        };

        window.addEventListener('mousemove', handleMouseMove);
        window.addEventListener('keydown', handleKeyDown);
        window.addEventListener('keyup', handleKeyUp);
        window.addEventListener('interaction-hover', handleHoverChange as EventListener);

        return () => {
            window.removeEventListener('mousemove', handleMouseMove);
            window.removeEventListener('keydown', handleKeyDown);
            window.removeEventListener('keyup', handleKeyUp);
            window.removeEventListener('interaction-hover', handleHoverChange as EventListener);
        };
    }, []);

    return (
        <div className="pointer-events-none fixed inset-0 z-[9999]">
            {/* TOOLTIP (CONTROL) */}
            <div 
                className={`absolute transition-opacity duration-100 ease-out flex flex-col items-start gap-1 ${tooltipData.visible ? 'opacity-100' : 'opacity-0'}`}
                style={{ 
                    left: tooltipData.x + 20, 
                    top: tooltipData.y + 20,
                }}
            >
                {/* Decorative Connector */}
                <div className="absolute -top-3 -left-3 w-4 h-4 border-l-2 border-t-2 border-[#00F0FF]" />

                <div className="bg-black/90 border border-[#00F0FF] px-4 py-2 shadow-[0_0_15px_rgba(0,240,255,0.3)] backdrop-blur-md">
                    <div className="flex items-center gap-2 mb-1">
                        <div className="w-1.5 h-1.5 bg-[#00F0FF] animate-pulse rounded-full" />
                        <span className="text-[9px] font-['Roboto_Mono'] text-[#00F0FF] tracking-widest uppercase">
                            OBJECT IDENTIFIER
                        </span>
                    </div>
                    <span className="font-['Teko'] text-2xl text-white tracking-wide uppercase leading-none">
                        {tooltipData.name}
                    </span>
                </div>
            </div>

            {/* TOAST (SHIFT) */}
            <div className={`
                absolute bottom-24 left-1/2 -translate-x-1/2 
                bg-[#F2D019] text-black px-8 py-3 
                transform transition-all duration-300 cubic-bezier(0.175, 0.885, 0.32, 1.275)
                clip-path-polygon-[0_0,_100%_0,_95%_100%,_5%_100%]
                border-2 border-white shadow-[0_0_30px_rgba(242,208,25,0.5)]
                flex items-center gap-4
                ${toast.visible ? 'translate-y-0 opacity-100 scale-100' : 'translate-y-10 opacity-0 scale-90'}
            `}>
                <div className="w-6 h-6 border-2 border-black flex items-center justify-center animate-spin">
                    <div className="w-2 h-2 bg-black" />
                </div>
                <div>
                    <div className="font-['Teko'] text-3xl font-bold leading-none tracking-widest">COPIED</div>
                    <div className="font-mono text-[10px] font-bold uppercase tracking-[0.2em] opacity-80">{toast.msg}</div>
                </div>
            </div>
        </div>
    );
};

// --- PROVIDER ---
// Optimized provider that dispatches custom events to avoid re-rendering the whole tree
export const InteractionProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    const setHoveredItem = (name: string | null) => {
        window.dispatchEvent(new CustomEvent('interaction-hover', { detail: name }));
    };

    return (
        <InteractionContext.Provider value={{ setHoveredItem }}>
            {children}
            <InteractionUI />
        </InteractionContext.Provider>
    );
};

import React, { useState, useCallback } from 'react';
import { ThreeSky } from './components/environment/ThreeSky';
import { Horizon } from './components/environment/Horizon';
import { Floor } from './components/environment/Floor';
import { SandFog } from './components/effects/SandFog';
import { DustParticles } from './components/effects/DustParticles/index';
import { Navigation } from './components/ui/Navigation';
import { IntroScreen } from './components/ui/IntroScreen';
import { OverlayEffects } from './components/ui/OverlayEffects';
import { useParallaxScroll } from './hooks/useParallaxScroll';
import { StackScreen } from './components/ui/StackScreen';
import { LootMapScreen } from './features/LootMapScreen';
import { ProjectsScreen } from './features/ProjectsScreen';
import { InteractionProvider } from './features/InteractionSystem';

type InterfaceType = 'NONE' | 'STACK' | 'LOOTMAP' | 'PROJECTS';

const App: React.FC = () => {
    const [hasStarted, setHasStarted] = useState(false);
    const [activeInterface, setActiveInterface] = useState<InterfaceType>('NONE');

    const { viewerRef, scrollRef, activeIndex, scrollToSection } = useParallaxScroll();

    const handlePortalNavigation = useCallback(() => {
        scrollToSection(2);
        setTimeout(() => {
            setActiveInterface('STACK');
        }, 800);
    }, [scrollToSection]);

    const handleCloseInterface = () => setActiveInterface('NONE');

    return (
        <InteractionProvider>
            <div className="bg-black overflow-hidden relative h-screen w-screen select-none font-sans text-white antialiased">

                {/* INTERFACES (MODALS) */}
                {activeInterface === 'STACK' && <StackScreen onClose={handleCloseInterface} />}
                {activeInterface === 'LOOTMAP' && <LootMapScreen onClose={handleCloseInterface} />}
                {activeInterface === 'PROJECTS' && <ProjectsScreen onClose={handleCloseInterface} />}

                {/* PANTALLA DE INICIO */}
                {!hasStarted && <IntroScreen onStart={() => setHasStarted(true)} />}

                {/* POST-PROCESADO */}
                <OverlayEffects />

                {/* 1. LAYER: ENVIRONMENT */}
                <div className="absolute inset-0 z-0 pointer-events-none">
                    <ThreeSky scrollRef={scrollRef} />
                </div>

                {/* 2. LAYER: WORLD */}
                <div 
                    ref={viewerRef}
                    id="viewer" 
                    className="relative z-10 w-full h-full overflow-x-auto scroll-smooth snap-x snap-mandatory flex flex-row [&::-webkit-scrollbar]:hidden [-ms-overflow-style:'none'] [scrollbar-width:'none']"
                >
                    <Horizon 
                        onOpenStack={() => setActiveInterface('STACK')} 
                        onOpenLootMap={() => setActiveInterface('LOOTMAP')}
                        onOpenProjects={() => setActiveInterface('PROJECTS')}
                        onPortalNavigate={handlePortalNavigation}
                        activeIndex={activeIndex}
                    />
                    <Floor />

                    <div className="min-w-[100vw] h-full flex-shrink-0 snap-start pointer-events-none" />
                    <div className="min-w-[100vw] h-full flex-shrink-0 snap-start pointer-events-none" />
                    <div className="min-w-[100vw] h-full flex-shrink-0 snap-start pointer-events-none" />
                </div>

                {/* 3. LAYER: EFFECTS */}
                <SandFog scrollRef={scrollRef} />
                <DustParticles scrollRef={scrollRef} />

                {/* 4. LAYER: UI (HUD) */}
                <div className={`transition-opacity duration-1000 ${hasStarted ? 'opacity-100' : 'opacity-0'}`}>
                    <Navigation 
                        totalPanes={3} 
                        activeIndex={activeIndex} 
                        onDotClick={scrollToSection} 
                    />
                </div>
            </div>
        </InteractionProvider>
    );
};

export default App;

import React, { useState } from 'react';
import { useInteraction } from '../../features/InteractionSystem';

interface GameImageProps {
    src: string;
    alt: string;
    className?: string; // Para el contenedor
    imgClassName?: string; // Para la imagen interna (opcional)
    priority?: boolean;
    style?: React.CSSProperties;
}

export const GameImage: React.FC<GameImageProps> = ({ 
    src, 
    alt, 
    className = "", 
    imgClassName = "",
    priority = false, 
    style = {} 
}) => {
    const [isLoaded, setIsLoaded] = useState(false);
    const { setHoveredItem } = useInteraction();

    return (
        <div 
            className={`relative overflow-hidden ${className}`}
            onMouseEnter={() => setHoveredItem(alt)}
            onMouseLeave={() => setHoveredItem(null)}
        >
            {!isLoaded && (
                <div className="absolute inset-0 flex items-center justify-center z-10 bg-black/20 backdrop-blur-sm transition-opacity duration-300">
                    <div className="relative w-8 h-8 md:w-12 md:h-12">
                        <div className="absolute inset-0 border-2 border-t-white/80 border-r-transparent border-b-white/80 border-l-transparent rounded-full animate-spin"></div>
                    </div>
                </div>
            )}

            <img
                src={src}
                alt={alt}
                draggable="false" // UX: Previene arrastre fantasma de imágenes
                loading={priority ? "eager" : "lazy"}
                fetchPriority={priority ? "high" : "low"}
                decoding="async"
                onLoad={() => setIsLoaded(true)}
                style={style}
                className={`
                    transition-opacity duration-700 ease-out select-none
                    ${isLoaded ? 'opacity-100' : 'opacity-0'}
                    ${imgClassName || 'w-full h-full object-cover'} 
                `}
            />
        </div>
    );
};

@tailwind base;
@tailwind components;
@tailwind utilities;

/* --- CONFIGURACIÓN GLOBAL --- */
html, body, #root {
    cursor: auto !important;
    background-color: black;
}

/* --- INTERACTION SYSTEM --- */
.interaction-target {
    transition: filter 0.2s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    cursor: crosshair; /* Tactical feel */
}

/* White Outline Effect using multiple drop-shadows for a stroke-like appearance on PNGs */
.interaction-target:hover {
    filter: drop-shadow(1px 0 0 white) 
            drop-shadow(-1px 0 0 white) 
            drop-shadow(0 1px 0 white) 
            drop-shadow(0 -1px 0 white)
            brightness(1.1);
    z-index: 50;
}

/* --- SCROLLBAR PERSONALIZADO SCI-FI --- */
.sci-fi-scroll {
    scrollbar-width: thin;
    scrollbar-color: #333 rgba(255, 255, 255, 0.05);
}

.sci-fi-scroll::-webkit-scrollbar {
    width: 6px;
    height: 6px;
}

.sci-fi-scroll::-webkit-scrollbar-track {
    background: rgba(0, 0, 0, 0.3);
}

.sci-fi-scroll::-webkit-scrollbar-thumb {
    background: #444;
    border-radius: 10px;
    transition: background 0.2s;
}

.sci-fi-scroll::-webkit-scrollbar-thumb:hover {
    background: #F2D019;
}

/* --- ANIMACIONES DE ALTO RENDIMIENTO (GPU) --- */
@keyframes drift-slow {
    0% { transform: translateX(0); }
    100% { transform: translateX(-25%); }
}

@keyframes morph {
    0% { border-radius: 60% 40% 30% 70% / 60% 30% 70% 40%; }
    50% { border-radius: 30% 60% 70% 40% / 50% 60% 30% 60%; }
    100% { border-radius: 60% 40% 30% 70% / 60% 30% 70% 40%; }
}

@keyframes undulate {
    0%, 100% { transform: translateY(0); }
    50% { transform: translateY(-25px); }
}

@keyframes grain-flow {
    0% { transform: translate(0, 0); }
    100% { transform: translate(-5%, -5%); }
}

@keyframes scanline-move {
    0% { top: -10%; opacity: 0; }
    10% { opacity: 1; }
    90% { opacity: 1; }
    100% { top: 110%; opacity: 0; }
}

@keyframes portal-pulse {
    0%, 100% { filter: drop-shadow(0 0 15px rgba(0, 240, 255, 0.4)) brightness(1); }
    50% { filter: drop-shadow(0 0 40px rgba(0, 240, 255, 0.8)) brightness(1.2); }
}

@keyframes glitch-text {
    0% { transform: translate(0); text-shadow: 2px 2px 0px #000; }
    2% { transform: translate(-2px, 2px); text-shadow: -2px 0 cyan, 2px 0 red; }
    4% { transform: translate(2px, -1px); text-shadow: 2px 0 cyan, -2px 0 red; }
    6% { transform: translate(0); }
    100% { transform: translate(0); }
}

@keyframes energy-arc {
    0% { transform: scaleX(0) translateX(-100%); opacity: 0; }
    50% { transform: scaleX(1) translateX(0); opacity: 1; }
    100% { transform: scaleX(0) translateX(100%); opacity: 0; }
}

@keyframes float-tech {
    0%, 100% { transform: translateY(0) rotate(0deg); }
    50% { transform: translateY(-15px) rotate(5deg); }
}

/* --- NUEVAS ANIMACIONES DE INTERFAZ --- */

/* Movimiento de fondo infinito */
@keyframes bg-pan {
    0% { background-position: 0% 0%; }
    100% { background-position: 100px 100px; }
}

/* Entrada secuencial (Stagger) */
@keyframes fade-up {
    0% { opacity: 0; transform: translateY(30px); }
    100% { opacity: 1; transform: translateY(0); }
}

.animate-portal-fx { animation: portal-pulse 3s ease-in-out infinite; }
.animate-glitch-active { animation: glitch-text 4s linear infinite; }
.animate-energy { animation: energy-arc 2s cubic-bezier(0.4, 0, 0.2, 1) infinite; }
.animate-float-tech { animation: float-tech 6s ease-in-out infinite; }

.animate-stack-entry { animation: stack-entry 0.4s cubic-bezier(0.16, 1, 0.3, 1) forwards; }
.animate-grain { animation: grain-flow 0.5s steps(3) infinite; }
.animate-drift { animation: drift-slow 80s linear infinite; }
.animate-blob-1 { animation: morph 10s ease-in-out infinite, undulate 6s ease-in-out infinite alternate; }
.animate-blob-2 { animation: morph 14s ease-in-out infinite, undulate 8s ease-in-out infinite alternate; }
.animate-blob-3 { animation: morph 11s ease-in-out infinite, undulate 5s ease-in-out infinite alternate; }
.animate-float { animation: undulate 6s ease-in-out infinite; }
.animate-scanline { animation: scanline-move 4s linear infinite; }
.animate-dust-wander { animation: dust-wander 40s linear infinite; }

/* Utilitarios de Animación */
.animate-bg-pan { animation: bg-pan 20s linear infinite; }

.animate-fade-up { 
    opacity: 0; /* Comienza invisible */
    animation: fade-up 0.6s cubic-bezier(0.16, 1, 0.3, 1) forwards; 
}

.delay-100 { animation-delay: 100ms; }
.delay-200 { animation-delay: 200ms; }
.delay-300 { animation-delay: 300ms; }
.delay-400 { animation-delay: 400ms; }
.delay-500 { animation-delay: 500ms; }

