import React, { createContext, useContext, useState, useEffect, useRef } from 'react';
import { sfx } from '../utils/SoundManager';

// --- TYPE DEFINITIONS ---
interface InteractionData {
    name: string;
    src?: string;
}

interface InteractionContextType {
    setHoveredItem: (data: InteractionData | null) => void;
}

const InteractionContext = createContext<InteractionContextType>({
    setHoveredItem: () => {},
});

export const useInteraction = () => useContext(InteractionContext);

// --- HOOK: useImageInteraction ---
// Updated to accept src for preview generation
export const useImageInteraction = (name: string, src?: string) => {
    const { setHoveredItem } = useInteraction();
    return {
        onMouseEnter: () => setHoveredItem({ name, src }),
        onMouseLeave: () => setHoveredItem(null),
        className: "interaction-target" 
    };
};

// --- VISUAL UI COMPONENT ---
export const InteractionUI: React.FC = () => {
    const [tooltipData, setTooltipData] = useState<{ name: string; x: number; y: number; visible: boolean }>({ 
        name: '', x: 0, y: 0, visible: false 
    });

    // State for the Top Preview Box
    const [previewData, setPreviewData] = useState<InteractionData | null>(null);
    const [toast, setToast] = useState<{ msg: string; visible: boolean }>({ msg: '', visible: false });

    // Internal refs
    const hoveredDataRef = useRef<InteractionData | null>(null);
    const mousePosRef = useRef({ x: 0, y: 0 });

    useEffect(() => {
        const handleMouseMove = (e: MouseEvent) => {
            mousePosRef.current = { x: e.clientX, y: e.clientY };

            // Tooltip logic (Ctrl key)
            if (e.ctrlKey && hoveredDataRef.current) {
                setTooltipData(prev => ({
                    ...prev,
                    x: e.clientX,
                    y: e.clientY,
                    visible: true,
                    name: hoveredDataRef.current?.name || ''
                }));
            } else {
                setTooltipData(prev => ({ ...prev, visible: false }));
            }
        };

        const handleKeyDown = (e: KeyboardEvent) => {
            if (e.key === 'Control') {
                if (hoveredDataRef.current) {
                    setTooltipData({
                        name: hoveredDataRef.current.name,
                        x: mousePosRef.current.x,
                        y: mousePosRef.current.y,
                        visible: true
                    });
                }
            }

            if (e.key === 'Shift') {
                if (hoveredDataRef.current) {
                    navigator.clipboard.writeText(hoveredDataRef.current.name).then(() => {
                        sfx.play('CLICK');
                        setToast({ msg: `DATA ACQUIRED: ${hoveredDataRef.current?.name}`, visible: true });
                        setTimeout(() => setToast(prev => ({ ...prev, visible: false })), 2000);
                    }).catch(err => console.error('Clipboard failed', err));
                }
            }
        };

        const handleKeyUp = (e: KeyboardEvent) => {
            if (e.key === 'Control') {
                setTooltipData(prev => ({ ...prev, visible: false }));
            }
        };

        const handleHoverChange = (e: CustomEvent) => {
            const data = e.detail as InteractionData | null;
            hoveredDataRef.current = data;

            // Update Preview Box State immediately
            setPreviewData(data);

            if (!data) {
                setTooltipData(prev => ({ ...prev, visible: false }));
            } else if (data && tooltipData.visible) {
                setTooltipData(prev => ({ ...prev, name: data.name }));
            }
        };

        window.addEventListener('mousemove', handleMouseMove);
        window.addEventListener('keydown', handleKeyDown);
        window.addEventListener('keyup', handleKeyUp);
        window.addEventListener('interaction-hover', handleHoverChange as EventListener);

        return () => {
            window.removeEventListener('mousemove', handleMouseMove);
            window.removeEventListener('keydown', handleKeyDown);
            window.removeEventListener('keyup', handleKeyUp);
            window.removeEventListener('interaction-hover', handleHoverChange as EventListener);
        };
    }, [tooltipData.visible]);

    return (
        <div className="pointer-events-none fixed inset-0 z-[9999]">

            {/* --- TOP PREVIEW HUD (TARGET LOCKED) --- */}
            <div className={`
                absolute top-4 left-1/2 -translate-x-1/2 
                transition-all duration-300 ease-out
                flex flex-col items-center gap-2
                ${previewData ? 'opacity-100 translate-y-0' : 'opacity-0 -translate-y-4'}
            `}>
                <div className="bg-black/90 border border-[#F2D019] p-1 shadow-[0_0_20px_rgba(242,208,25,0.2)] backdrop-blur-md flex items-center gap-3 pr-4">
                    {/* Thumbnail Preview */}
                    <div className="w-16 h-16 border border-white/20 bg-[#111] overflow-hidden relative">
                        {previewData?.src ? (
                            <img 
                                src={previewData.src} 
                                className="w-full h-full object-contain object-center" 
                                alt="Preview" 
                            />
                        ) : (
                            <div className="w-full h-full flex items-center justify-center text-xs text-gray-600 font-mono">NO IMG</div>
                        )}
                        {/* Crosshair Overlay on thumb */}
                        <div className="absolute inset-0 border border-[#F2D019]/30">
                            <div className="absolute top-1/2 left-0 w-full h-[1px] bg-[#F2D019]/30" />
                            <div className="absolute top-0 left-1/2 w-[1px] h-full bg-[#F2D019]/30" />
                        </div>
                    </div>

                    {/* Text Info */}
                    <div className="flex flex-col">
                        <span className="text-[10px] font-mono text-[#F2D019] tracking-widest animate-pulse">TARGET LOCKED</span>
                        <span className="font-['Teko'] text-2xl text-white uppercase tracking-wide leading-none max-w-[200px] truncate">
                            {previewData?.name}
                        </span>
                        <span className="text-[9px] font-mono text-gray-500 uppercase tracking-wider">
                            SHIFT + CLICK TO COPY
                        </span>
                    </div>
                </div>

                {/* Connecting Line to top edge */}
                <div className="w-[1px] h-4 bg-gradient-to-b from-[#F2D019] to-transparent opacity-50" />
            </div>


            {/* --- MOUSE TOOLTIP (CONTROL) --- */}
            <div 
                className={`absolute transition-opacity duration-100 ease-out flex flex-col items-start gap-1 ${tooltipData.visible ? 'opacity-100' : 'opacity-0'}`}
                style={{ left: tooltipData.x + 20, top: tooltipData.y + 20 }}
            >
                <div className="absolute -top-3 -left-3 w-4 h-4 border-l-2 border-t-2 border-[#00F0FF]" />
                <div className="bg-black/90 border border-[#00F0FF] px-4 py-2 shadow-[0_0_15px_rgba(0,240,255,0.3)] backdrop-blur-md">
                    <div className="flex items-center gap-2 mb-1">
                        <div className="w-1.5 h-1.5 bg-[#00F0FF] animate-pulse rounded-full" />
                        <span className="text-[9px] font-['Roboto_Mono'] text-[#00F0FF] tracking-widest uppercase">
                            OBJECT IDENTIFIER
