import React, { useState } from 'react';
import { useImageInteraction } from '../../features/InteractionSystem';

interface GameImageProps {
    src: string;
    alt: string;
    className?: string;
    imgClassName?: string;
    priority?: boolean;
    style?: React.CSSProperties;
}

export const GameImage: React.FC<GameImageProps> = ({ 
    src, 
    alt, 
    className = "", 
    imgClassName = "",
    priority = false, 
    style = {} 
}) => {
    const [isLoaded, setIsLoaded] = useState(false);

    // Automatically pass src to the interaction system
    const { onMouseEnter, onMouseLeave, className: interactionClass } = useImageInteraction(alt, src);

    return (
        <div 
            className={`relative overflow-hidden ${className}`}
            onMouseEnter={onMouseEnter}
            onMouseLeave={onMouseLeave}
        >
            {!isLoaded && (
                <div className="absolute inset-0 flex items-center justify-center z-10 bg-black/20 backdrop-blur-sm transition-opacity duration-300">
                    <div className="relative w-8 h-8 md:w-12 md:h-12">
                        <div className="absolute inset-0 border-2 border-t-white/80 border-r-transparent border-b-white/80 border-l-transparent rounded-full animate-spin"></div>
                    </div>
                </div>
            )}

            <img
                src={src}
                alt={alt}
                draggable="false"
                loading={priority ? "eager" : "lazy"}
                fetchPriority={priority ? "high" : "low"}
                decoding="async"
                onLoad={() => setIsLoaded(true)}
                style={style}
                className={`
                    transition-opacity duration-700 ease-out select-none
                    ${isLoaded ? 'opacity-100' : 'opacity-0'}
                    ${interactionClass} 
                    ${imgClassName || 'w-full h-full object-cover'} 
                `}
            />
        </div>
    );
};

