import React from 'react';
import { ASSETS } from '../../config/assets';
import { sfx } from '../../utils/SoundManager';
import { WestZone, NorthZone, EastZone } from './HorizonZones';

interface HorizonProps {
    onOpenStack: () => void;
    onOpenLootMap: () => void;
    onOpenProjects: () => void;
    onPortalNavigate: () => void;
    activeIndex: number;
}

export const Horizon: React.FC<HorizonProps> = React.memo(({ onOpenStack, onOpenLootMap, onOpenProjects, onPortalNavigate, activeIndex }) => {

    const handleOpenStack = () => {
        sfx.play('OPEN');
        onOpenStack();
    };

    const handleHeroClick = () => {
        sfx.play('CLICK');
        handleOpenStack();
    }

    const handleMapClick = () => {
        sfx.play('OPEN');
        onOpenLootMap();
    }

    const handleQuestClick = () => {
        sfx.play('OPEN');
        onOpenProjects();
    }

    // NOTE: Interaction removed from Horizon Mask (Atmospheric Layer) as requested.
    // Use plain img tag without hooks for non-interactive background elements.

    return (
        <div id="horizon-wrapper" className="absolute left-0 z-10 pointer-events-none will-change-transform"
             style={{
                 width: '300vw',
                 bottom: 'calc(70vh - 15px)',
                 height: '35vh',
                 minHeight: '200px'
             }}>

            {/* OESTE (Left) */}
            <WestZone onMapClick={handleMapClick} />

            {/* NORTE (Center) */}
            <NorthZone 
                onPortalNavigate={onPortalNavigate} 
                onQuestClick={handleQuestClick}
                activeIndex={activeIndex} 
            />

            {/* ESTE (Right) */}
            <EastZone onHeroClick={handleHeroClick} />

            {/* MÁSCARA GLOBAL HORIZONTE (NO INTERACTIVA) */}
            <img 
                src={ASSETS.BG.HORIZON_MASK} 
                alt="Transición Horizonte" 
                className="absolute bottom-0 left-0 w-full object-contain object-bottom z-20 select-none pointer-events-auto opacity-80"
                style={{ 
                    height: '50%',
                    transform: 'scale(0.85)', 
                    transformOrigin: 'bottom center' 
                }}
            />
        </div>
    );
});

