import React, { useEffect, useRef } from 'react';
import * as THREE from 'three';

// --- CONFIGURACIÓN DE TELA (DARK MODE) ---
const config = {
    windForce: 0.18,
    baseColor: new THREE.Color(0x111111), // Negro más profundo
};

// --- SHADERS DE TELA MEJORADOS ---
const vertexShader = `
uniform float uTime;
uniform float uWindStrength;

varying vec2 vUv;
varying vec3 vNormal;
varying float vDisplacement;

void main() {
    vUv = uv;
    vec3 pos = position;

    // El pinFactor define qué partes se mueven. 
    // uv.x = 0 es la izquierda (atada). 
    // Queremos que ondee arriba y abajo, así que el movimiento es máximo en los extremos verticales (y=0, y=1) 
    // y en el borde libre (x=1).

    float xFactor = smoothstep(0.0, 1.0, uv.x);
    // Factor Y: Mayor en bordes superior/inferior, ligeramente menor al centro para "tensionar" la tela
    float yFactor = 1.0 + 0.3 * abs(uv.y - 0.5); 

    float intensity = xFactor * yFactor;

    // Ondas principales (Seno y Coseno combinados para aleatoriedad visual)
    float wave1 = sin(pos.x * 1.5 + pos.y * 0.8 + uTime * 2.2) * 0.6;
    float wave2 = cos(pos.x * 3.0 - pos.y * 1.5 + uTime * 4.0) * 0.25;
    float ripple = sin(uTime * 5.0 + pos.y * 12.0 + pos.x * 8.0) * 0.08;

    float displacement = (wave1 + wave2 + ripple) * uWindStrength * intensity;

    pos.z += displacement;

    // Sutil "encogimiento" de la tela al ondear
    pos.x -= abs(displacement) * 0.05 * xFactor;
    pos.y += sin(uTime * 0.5 + pos.x * 2.0) * 0.02 * intensity;

    vNormal = normalize(normalMatrix * normal);
    vDisplacement = displacement;

    gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
}
`;

const fragmentShader = `
uniform sampler2D uTexture;
uniform vec3 uBaseColor;
uniform float uTime;

varying vec2 vUv;
varying vec3 vNormal;
varying float vDisplacement;

void main() {
    vec4 mapTex = texture2D(uTexture, vUv);

    // 1. Micro-textura de tejido táctico (Kevlar/Nylon)
    float weaveScale = 900.0;
    float threadX = abs(sin(vUv.x * weaveScale));
    float threadY = abs(sin(vUv.y * weaveScale));
    float clothTexture = mix(0.85, 1.0, threadX * threadY);

    // 2. Colores
    vec3 goldColor = vec3(0.95, 0.82, 0.1); // #F2D019
    vec3 darkColor = uBaseColor;

    // El brillo de la textura define qué es bordado dorado
    float isGold = smoothstep(0.4, 0.6, mapTex.r);
    vec3 albedo = mix(darkColor, goldColor, mapTex.r * 0.9);

    // 3. Iluminación Cinematográfica
    vec3 lightDir = normalize(vec3(0.5, 0.5, 1.0));
    // Perturbar normales basándonos en el desplazamiento del vertex shader
    vec3 faceNormal = normalize(vNormal + vec3(0.0, 0.0, vDisplacement * 0.5));

    float diff = max(dot(faceNormal, lightDir), 0.0);

    // Brillo para el bordado de oro
    vec3 viewDir = normalize(vec3(0.0, 0.0, 1.0));
    vec3 halfVec = normalize(lightDir + viewDir);
    float spec = pow(max(dot(faceNormal, halfVec), 0.0), 32.0);
    float goldSpec = isGold * spec * 1.5;

    // Sombras ambientales por pliegues
    float foldShadow = 1.0 - smoothstep(0.0, 0.8, abs(vDisplacement));
    foldShadow = mix(0.4, 1.0, foldShadow);

    // Brillo sutil de los bordes (Fresnel / Sheen)
    float sheen = pow(1.0 - max(dot(faceNormal, viewDir), 0.0), 3.0);
    vec3 sheenCol = mix(vec3(0.2), goldColor, isGold) * sheen * 0.5;

    vec3 lighting = vec3(0.25) + (vec3(0.75) * diff);

    vec3 finalColor = (albedo * lighting * foldShadow * clothTexture) + (vec3(1.0, 0.9, 0.6) * goldSpec) + sheenCol;

    // Añadir un poco de ruido de grano de película sutil
    float noise = fract(sin(dot(vUv, vec2(12.9898, 78.233) * uTime)) * 43758.5453);
    finalColor += (noise - 0.5) * 0.02;

    gl_FragColor = vec4(finalColor, 1.0);
}
`;

// GENERADOR DE TEXTURA ESTILO "DARK OPS"
const createProceduralMapTexture = () => {
    const canvas = document.createElement('canvas');
    canvas.width = 512;
    canvas.height = 768;
    const ctx = canvas.getContext('2d');

    if (ctx) {
        // Fondo NEGRO
        ctx.fillStyle = '#050505';
        ctx.fillRect(0, 0, 512, 768);

        // Grid Táctico (Hexagonos falsos y líneas)
        ctx.strokeStyle = '#1a1a1a';
        ctx.lineWidth = 1;
        ctx.beginPath();
        for(let x=0; x<=512; x+=32) { ctx.moveTo(x,0); ctx.lineTo(x,768); }
        for(let y=0; y<=768; y+=32) { ctx.moveTo(0,y); ctx.lineTo(512,y); }
        ctx.stroke();

        // Mapa Topográfico (Oro)
        ctx.strokeStyle = '#F2D019';
        ctx.lineWidth = 3;
        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';
        ctx.shadowColor = '#F2D019';
        ctx.shadowBlur = 8;

        // Forma de tierra abstracta
        ctx.beginPath();
        ctx.moveTo(100, 100);
        ctx.lineTo(400, 120);
        ctx.lineTo(450, 300);
        ctx.lineTo(380, 500);
        ctx.lineTo(120, 550);
        ctx.lineTo(80, 350);
        ctx.closePath();
        ctx.stroke();

        // Curvas de nivel
        ctx.lineWidth = 1;
        ctx.globalAlpha = 0.5;
        for(let i=1; i<4; i++) {
            ctx.strokeRect(100 + i*20, 100 + i*20, 312 - i*40, 468 - i*40);
        }
        ctx.globalAlpha = 1.0;
        ctx.shadowBlur = 0;

        // "X" Target (Rojo Intenso)
        ctx.strokeStyle = '#ff1100';
        ctx.lineWidth = 6;
        const xPos = 250, yPos = 400;
        ctx.beginPath();
        ctx.moveTo(xPos-20, yPos-20); ctx.lineTo(xPos+20, yPos+20);
        ctx.moveTo(xPos+20, yPos-20); ctx.lineTo(xPos-20, yPos+20);
        ctx.stroke();

        // Texto Estilo HUD
        ctx.fillStyle = '#F2D019';
        ctx.font = '900 45px "Teko"';
        ctx.textAlign = 'left';
        ctx.fillText('DEPLOYMENT: S07', 50, 70);

        ctx.fillStyle = '#fff';
        ctx.font = 'bold 20px "Roboto Mono"';
        ctx.fillText('LAT: 34.05 / LONG: -118.24', 50, 720);

        // Barras de progreso decorativas
        ctx.fillStyle = '#222';
        ctx.fillRect(50, 650, 412, 10);
        ctx.fillStyle = '#F2D019';
        ctx.fillRect(50, 650, 280, 10);
    }

    const texture = new THREE.CanvasTexture(canvas);
    texture.colorSpace = THREE.SRGBColorSpace;
    texture.anisotropy = 8;
    return { texture };
};

export const Flag: React.FC = () => {
    const containerRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        if (!containerRef.current) return;

        const width = containerRef.current.clientWidth;
        const height = containerRef.current.clientHeight;

        const scene = new THREE.Scene();
        const camera = new THREE.PerspectiveCamera(40, width / height, 0.1, 100);
        camera.position.set(0, 0, 4.0); 

        const renderer = new THREE.WebGLRenderer({ alpha: true, antialias: true, powerPreference: "high-performance" });
        renderer.setSize(width, height);
        renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
        containerRef.current.appendChild(renderer.domElement);

        const { texture } = createProceduralMapTexture();
        texture.needsUpdate = true;

        const material = new THREE.ShaderMaterial({
            vertexShader: vertexShader,
            fragmentShader: fragmentShader,
            uniforms: {
                uTexture: { value: texture },
                uTime: { value: 0 },
                uWindStrength: { value: config.windForce },
                uBaseColor: { value: config.baseColor }
            },
            side: THREE.DoubleSide,
        });

        // Aumentar segmentos para que la tela se vea más suave
        const geometry = new THREE.PlaneGeometry(1.8, 2.4, 45, 60);
        const mesh = new THREE.Mesh(geometry, material);

        scene.add(mesh);

        const clock = new THREE.Clock();
        let animationId: number;

        const animate = () => {
            animationId = requestAnimationFrame(animate);
            const time = clock.getElapsedTime();
            material.uniforms.uTime.value = time;
            renderer.render(scene, camera);
        };
        animate();

        const handleResize = () => {
            if (!containerRef.current) return;
            const newW = containerRef.current.clientWidth;
            const newH = containerRef.current.clientHeight;
            camera.aspect = newW / newH;
            camera.updateProjectionMatrix();
            renderer.setSize(newW, newH);
        };
        window.addEventListener('resize', handleResize);

        return () => {
            window.removeEventListener('resize', handleResize);
            cancelAnimationFrame(animationId);
            renderer.dispose();
            geometry.dispose();
            material.dispose();
            texture.dispose();
            if (containerRef.current) {
                containerRef.current.innerHTML = '';
            }
        };
    }, []);

    return <div ref={containerRef} className="w-full h-full pointer-events-none" />;
};

