import React, { useEffect, useRef } from 'react';
import * as THREE from 'three';

// --- CONFIGURACIÓN DE TELA TÁCTICA ---
const config = {
    windForce: 0.22,
    baseColor: new THREE.Color(0x080808), // Negro ultra profundo
};

// --- SHADER: TOP-PINNED TACTICAL CLOTH ---
const vertexShader = `
uniform float uTime;
uniform float uWindStrength;

varying vec2 vUv;
varying vec3 vNormal;
varying float vDisplacement;

void main() {
    vUv = uv;
    vec3 pos = position;

    // FÍSICA DE COLGADO:
    // uv.y = 1.0 es ARRIBA (Static)
    // uv.y = 0.0 es ABAJO (Maximum movement)

    // El pinFactor hace que la parte superior sea 0 (estática)
    // Usamos pow para que la rigidez sea mayor cerca de la barra superior
    float influence = pow(1.0 - uv.y, 1.8); 

    // Factor X: El centro ondea un poco menos que las esquinas inferiores
    float xFactor = 0.8 + 0.2 * abs(uv.x - 0.5) * 2.0;

    float intensity = influence * xFactor;

    // Simulación de viento direccional + turbulencia
    float wave1 = sin(pos.x * 2.0 + uTime * 2.5) * 0.5;
    float wave2 = cos(pos.y * 1.5 - uTime * 3.8) * 0.3;
    float flutter = sin(uTime * 10.0 + pos.x * 5.0 + pos.y * 5.0) * 0.05;

    float displacement = (wave1 + wave2 + flutter) * uWindStrength * intensity;

    // Aplicar desplazamiento en Z (profundidad del ondeado)
    pos.z += displacement;

    // Sutil efecto de péndulo lateral
    pos.x += sin(uTime * 0.8) * 0.03 * influence;

    // Acortamiento real de la tela al plegarse (Preservación de área aproximada)
    pos.y += abs(displacement) * 0.1 * influence;

    vNormal = normalize(normalMatrix * normal);
    vDisplacement = displacement;

    gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
}
`;

const fragmentShader = `
uniform sampler2D uTexture;
uniform vec3 uBaseColor;
uniform float uTime;

varying vec2 vUv;
varying vec3 vNormal;
varying float vDisplacement;

void main() {
    vec4 mapTex = texture2D(uTexture, vUv);

    // 1. TEXTURA RIPSTOP (Rejilla de Nylon Militar)
    // Crea pequeños cuadrados de refuerzo visibles al reflejar la luz
    float ripstopScale = 120.0;
    vec2 grid = abs(fract(vUv * ripstopScale - 0.5) - 0.5);
    float line = smoothstep(0.4, 0.5, max(grid.x, grid.y));
    float clothPattern = mix(0.92, 1.0, line);

    // 2. COLORES Y LOGO
    vec3 goldColor = vec3(0.95, 0.82, 0.1); // #F2D019
    float isLogo = mapTex.r; // Usamos el canal rojo como máscara de brillo

    vec3 albedo = mix(uBaseColor, goldColor, isLogo * 0.95);

    // 3. ILUMINACIÓN TÁCTICA
    vec3 lightDir = normalize(vec3(0.5, 1.0, 0.8));
    vec3 viewDir = normalize(vec3(0.0, 0.0, 1.0));

    // Perturbar normales para simular pliegues
    vec3 normal = normalize(vNormal + vec3(0.0, 0.0, vDisplacement * 0.8));

    float diff = max(dot(normal, lightDir), 0.0);

    // Brillo especular (Micro-brillo del nylon)
    float spec = pow(max(dot(reflect(-lightDir, normal), viewDir), 0.0), 16.0);
    float specMask = mix(0.2, 1.0, isLogo); // El logo dorado brilla más

    // Sombras profundas en los valles de la tela
    float shadow = smoothstep(-0.5, 0.5, vDisplacement);
    shadow = mix(0.3, 1.0, shadow);

    vec3 finalColor = albedo * (diff + 0.2) * shadow * clothPattern;
    finalColor += vec3(0.8, 0.7, 0.4) * spec * 0.3 * specMask;

    // Efecto de desgaste en bordes (vignette sutil en la tela)
    float edgeMask = smoothstep(0.0, 0.05, vUv.x) * smoothstep(1.0, 0.95, vUv.x) *
                     smoothstep(0.0, 0.05, vUv.y) * smoothstep(1.0, 0.95, vUv.y);

    finalColor *= mix(0.7, 1.0, edgeMask);

    gl_FragColor = vec4(finalColor, 1.0);
}
`;

// GENERADOR DE DISEÑO "OPERACIONES ESPECIALES"
const createTacticalMapTexture = () => {
    const canvas = document.createElement('canvas');
    canvas.width = 512;
    canvas.height = 768;
    const ctx = canvas.getContext('2d');

    if (ctx) {
        // Fondo Gris muy oscuro (Casi negro ripstop)
        ctx.fillStyle = '#080808';
        ctx.fillRect(0, 0, 512, 768);

        // Marco de refuerzo (Borde de la bandera)
        ctx.strokeStyle = '#151515';
        ctx.lineWidth = 40;
        ctx.strokeRect(20, 20, 472, 728);

        // DISEÑO CENTRAL
        ctx.shadowColor = '#F2D019';
        ctx.strokeStyle = '#F2D019';
        ctx.fillStyle = '#F2D019';

        // Círculos de radar / Escala
        ctx.lineWidth = 2;
        ctx.globalAlpha = 0.3;
        for(let i=1; i<5; i++) {
            ctx.beginPath();
            ctx.arc(256, 384, i*80, 0, Math.PI*2);
            ctx.stroke();
        }
        ctx.globalAlpha = 1.0;

        // Logo Abstracto "S07"
        ctx.font = '900 120px "Teko"';
        ctx.textAlign = 'center';
        ctx.fillText('SECTION 07', 256, 380);

        ctx.font = 'bold 30px "Roboto Mono"';
        ctx.fillText('TACTICAL OVERVIEW', 256, 430);

        // Grid de coordenadas
        ctx.lineWidth = 1;
        ctx.strokeStyle = '#222';
        for(let i=0; i<512; i+=64) {
            ctx.beginPath(); ctx.moveTo(i, 0); ctx.lineTo(i, 768); ctx.stroke();
        }
        for(let i=0; i<768; i+=64) {
            ctx.beginPath(); ctx.moveTo(0, i); ctx.lineTo(512, i); ctx.stroke();
        }

        // Elementos de UI Táctica (Esquinas)
        ctx.lineWidth = 4;
        ctx.strokeStyle = '#F2D019';
        // Top Left
        ctx.beginPath(); ctx.moveTo(50, 100); ctx.lineTo(100, 100); ctx.moveTo(50, 100); ctx.lineTo(50, 150); ctx.stroke();
        // Bot Right
        ctx.beginPath(); ctx.moveTo(462, 668); ctx.lineTo(412, 668); ctx.moveTo(462, 668); ctx.lineTo(462, 618); ctx.stroke();

        // Warning bar
        ctx.fillStyle = '#F2D019';
        ctx.fillRect(100, 680, 312, 5);
        ctx.font = '12px "Roboto Mono"';
        ctx.fillText('CLASSIFIED // DO NOT REPLICATE', 256, 710);
    }

    const texture = new THREE.CanvasTexture(canvas);
    texture.colorSpace = THREE.SRGBColorSpace;
    texture.anisotropy = 16;
    return { texture };
};

export const Flag: React.FC = () => {
    const containerRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        if (!containerRef.current) return;

        const width = containerRef.current.clientWidth;
        const height = containerRef.current.clientHeight;

        const scene = new THREE.Scene();
        const camera = new THREE.PerspectiveCamera(35, width / height, 0.1, 100);
        camera.position.set(0, 0.2, 5.0); // Ajustamos cámara para ver el estandarte

        const renderer = new THREE.WebGLRenderer({ alpha: true, antialias: true });
        renderer.setSize(width, height);
        renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
        containerRef.current.appendChild(renderer.domElement);

        const { texture } = createTacticalMapTexture();
        texture.needsUpdate = true;

        const material = new THREE.ShaderMaterial({
            vertexShader: vertexShader,
            fragmentShader: fragmentShader,
            uniforms: {
                uTexture: { value: texture },
                uTime: { value: 0 },
                uWindStrength: { value: config.windForce },
                uBaseColor: { value: config.baseColor }
            },
            side: THREE.DoubleSide,
            transparent: true,
        });

        // Estandarte vertical con alta densidad de polígonos para suavidad
        const geometry = new THREE.PlaneGeometry(1.9, 2.7, 50, 70);
        const mesh = new THREE.Mesh(geometry, material);

        scene.add(mesh);

        const clock = new THREE.Clock();
        let animationId: number;

        const animate = () => {
            animationId = requestAnimationFrame(animate);
            const time = clock.getElapsedTime();
            material.uniforms.uTime.value = time;
            renderer.render(scene, camera);
        };
        animate();

        const handleResize = () => {
            if (!containerRef.current) return;
            const newW = containerRef.current.clientWidth;
            const newH = containerRef.current.clientHeight;
            camera.aspect = newW / newH;
            camera.updateProjectionMatrix();
            renderer.setSize(newW, newH);
        };
        window.addEventListener('resize', handleResize);

        return () => {
            window.removeEventListener('resize', handleResize);
            cancelAnimationFrame(animationId);
            renderer.dispose();
            geometry.dispose();
            material.dispose();
            texture.dispose();
            if (containerRef.current) {
                containerRef.current.innerHTML = '';
            }
        };
    }, []);

    return <div ref={containerRef} className="w-full h-full pointer-events-none" />;
};

