import React, { useEffect, useRef } from 'react';
import * as THREE from 'three';

// --- CONFIGURACIÓN DE TELA TÁCTICA ---
const config = {
    windForce: 0.22,
    baseColor: new THREE.Color(0x111111), // Negro carbón
};

// --- SHADER: TOP-PINNED TACTICAL CLOTH ---
const vertexShader = `
uniform float uTime;
uniform float uWindStrength;

varying vec2 vUv;
varying vec3 vNormal;
varying float vDisplacement;

void main() {
    vUv = uv;
    vec3 pos = position;

    // FÍSICA DE COLGADO:
    // uv.y = 1.0 es ARRIBA (Estático)
    float influence = pow(1.0 - uv.y, 1.6); 

    float intensity = influence * (0.8 + 0.2 * sin(uv.x * 3.0));

    float wave1 = sin(pos.x * 2.5 + uTime * 2.2) * 0.4;
    float wave2 = cos(pos.y * 2.0 - uTime * 3.0) * 0.25;
    float flutter = sin(uTime * 8.0 + pos.x * 10.0) * 0.04;

    float displacement = (wave1 + wave2 + flutter) * uWindStrength * intensity;

    pos.z += displacement;
    pos.y += abs(displacement) * 0.12 * influence;

    vNormal = normalize(normalMatrix * normal);
    vDisplacement = displacement;

    gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
}
`;

const fragmentShader = `
uniform sampler2D uTexture;
uniform vec3 uBaseColor;
uniform float uTime;

varying vec2 vUv;
varying vec3 vNormal;
varying float vDisplacement;

void main() {
    vec4 mapTex = texture2D(uTexture, vUv);

    // Textura Ripstop sutil
    float ripstopScale = 150.0;
    vec2 grid = abs(fract(vUv * ripstopScale - 0.5) - 0.5);
    float line = smoothstep(0.4, 0.5, max(grid.x, grid.y));
    float clothPattern = mix(0.94, 1.0, line);

    vec3 accentColor = vec3(0.95, 0.82, 0.1); // #F2D019

    // Máscara de diseño basada en la textura generada
    float isAccent = mapTex.r; 
    vec3 albedo = mix(uBaseColor, accentColor, isAccent);

    // Iluminación
    vec3 lightDir = normalize(vec3(0.5, 1.0, 1.0));
    vec3 normal = normalize(vNormal + vec3(0.0, 0.0, vDisplacement * 0.6));
    float diff = max(dot(normal, lightDir), 0.0);

    // Brillo del material sintético
    float spec = pow(max(dot(reflect(-lightDir, normal), vec3(0.0, 0.0, 1.0)), 0.0), 20.0);

    vec3 finalColor = albedo * (diff + 0.3) * clothPattern;
    finalColor += accentColor * spec * 0.4 * isAccent; // El amarillo brilla más

    gl_FragColor = vec4(finalColor, 1.0);
}
`;

// GENERADOR DE DISEÑO TÁCTICO "HIGH-VIS"
const createTacticalMapTexture = () => {
    const canvas = document.createElement('canvas');
    canvas.width = 512;
    canvas.height = 768;
    const ctx = canvas.getContext('2d');

    if (ctx) {
        // Fondo Negro
        ctx.fillStyle = '#111111';
        ctx.fillRect(0, 0, 512, 768);

        // --- HAZARD STRIPES (Base) ---
        const stripeWidth = 40;
        ctx.fillStyle = '#F2D019';
        for(let i=0; i<15; i++) {
            ctx.beginPath();
            ctx.moveTo(i * stripeWidth * 2, 768);
            ctx.lineTo(i * stripeWidth * 2 + stripeWidth, 768);
            ctx.lineTo(i * stripeWidth * 2 + stripeWidth - 100, 668);
            ctx.lineTo(i * stripeWidth * 2 - 100, 668);
            ctx.fill();
        }

        // --- MARCO SUPERIOR E INFERIOR ---
        ctx.fillStyle = '#F2D019';
        ctx.fillRect(0, 0, 512, 60);
        ctx.fillRect(0, 668, 512, 10);

        // --- CONTENIDO CENTRAL ---
        ctx.textAlign = 'center';

        // Gran "07"
        ctx.font = '900 300px "Teko"';
        ctx.fillStyle = '#F2D019';
        ctx.globalAlpha = 0.15;
        ctx.fillText('07', 256, 450);
        ctx.globalAlpha = 1.0;

        // Texto Identificador
        ctx.font = 'bold 80px "Teko"';
        ctx.fillText('SEC-07', 256, 350);

        ctx.font = '900 40px "Roboto Mono"';
        ctx.fillStyle = '#000';
        ctx.fillText('OPERATIONAL MAP', 256, 45);

        // Detalles Tácticos
        ctx.strokeStyle = '#F2D019';
        ctx.lineWidth = 2;
        ctx.strokeRect(50, 100, 412, 530);

        // Grid interno
        ctx.beginPath();
        ctx.globalAlpha = 0.3;
        for(let i=100; i<630; i+=80) {
            ctx.moveTo(50, i); ctx.lineTo(462, i);
        }
        for(let i=50; i<462; i+=80) {
            ctx.moveTo(i, 100); ctx.lineTo(i, 630);
        }
        ctx.stroke();
        ctx.globalAlpha = 1.0;

        // Crosshair central
        ctx.lineWidth = 4;
        ctx.beginPath();
        ctx.moveTo(236, 384); ctx.lineTo(276, 384);
        ctx.moveTo(256, 364); ctx.lineTo(256, 404);
        ctx.stroke();
    }

    const texture = new THREE.CanvasTexture(canvas);
    texture.colorSpace = THREE.SRGBColorSpace;
    texture.anisotropy = 16;
    return { texture };
};

export const Flag: React.FC = () => {
    const containerRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        if (!containerRef.current) return;

        const width = containerRef.current.clientWidth;
        const height = containerRef.current.clientHeight;

        const scene = new THREE.Scene();
        const camera = new THREE.PerspectiveCamera(35, width / height, 0.1, 100);
        camera.position.set(0, 0, 5.2); 

        const renderer = new THREE.WebGLRenderer({ alpha: true, antialias: true });
        renderer.setSize(width, height);
        renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
        containerRef.current.appendChild(renderer.domElement);

        const { texture } = createTacticalMapTexture();
        texture.needsUpdate = true;

        const material = new THREE.ShaderMaterial({
            vertexShader: vertexShader,
            fragmentShader: fragmentShader,
            uniforms: {
                uTexture: { value: texture },
                uTime: { value: 0 },
                uWindStrength: { value: config.windForce },
                uBaseColor: { value: config.baseColor }
            },
            side: THREE.DoubleSide,
            transparent: true,
        });

        const geometry = new THREE.PlaneGeometry(2.0, 2.8, 50, 70);
        const mesh = new THREE.Mesh(geometry, material);
        scene.add(mesh);

        const clock = new THREE.Clock();
        let animationId: number;

        const animate = () => {
            animationId = requestAnimationFrame(animate);
            material.uniforms.uTime.value = clock.getElapsedTime();
            renderer.render(scene, camera);
        };
        animate();

        const handleResize = () => {
            if (!containerRef.current) return;
            const newW = containerRef.current.clientWidth;
            const newH = containerRef.current.clientHeight;
            camera.aspect = newW / newH;
            camera.updateProjectionMatrix();
            renderer.setSize(newW, newH);
        };
        window.addEventListener('resize', handleResize);

        return () => {
            window.removeEventListener('resize', handleResize);
            cancelAnimationFrame(animationId);
            renderer.dispose();
            geometry.dispose();
            material.dispose();
            texture.dispose();
            if (containerRef.current) containerRef.current.innerHTML = '';
        };
    }, []);

    return <div ref={containerRef} className="w-full h-full pointer-events-none" />;
};

import React, { createContext, useContext, useState, useEffect, useRef } from 'react';
import { sfx } from '../utils/SoundManager';

// --- TYPE DEFINITIONS ---
interface InteractionData {
    name: string;
    src?: string;
}

interface InteractionContextType {
    setHoveredItem: (data: InteractionData | null) => void;
}

const InteractionContext = createContext<InteractionContextType>({
    setHoveredItem: () => {},
});

export const useInteraction = () => useContext(InteractionContext);

// --- UTILITY: Robust Copy to Clipboard ---
const copyToClipboard = (text: string): Promise<void> => {
    // Try modern API first if available and in secure context
    if (navigator.clipboard && window.isSecureContext) {
        return navigator.clipboard.writeText(text);
    } else {
        // Fallback: Hidden textarea (Legacy approach for restricted environments)
        return new Promise((resolve, reject) => {
            try {
                const textArea = document.createElement("textarea");
                textArea.value = text;
                textArea.style.position = "fixed";
                textArea.style.left = "-9999px";
                textArea.style.top = "0";
                document.body.appendChild(textArea);
                textArea.focus();
                textArea.select();
                const successful = document.execCommand('copy');
                document.body.removeChild(textArea);
                if (successful) resolve();
                else reject(new Error('Fallback copy failed'));
            } catch (err) {
                reject(err);
            }
        });
    }
};

// --- HOOK: useImageInteraction ---
export const useImageInteraction = (name: string, src?: string) => {
    const { setHoveredItem } = useInteraction();
    return {
        onMouseEnter: () => setHoveredItem({ name, src }),
        onMouseLeave: () => setHoveredItem(null),
        className: "interaction-target" 
    };
};

// --- VISUAL UI COMPONENT ---
export const InteractionUI: React.FC = () => {
    const [tooltipData, setTooltipData] = useState<{ name: string; x: number; y: number; visible: boolean }>({ 
        name: '', x: 0, y: 0, visible: false 
    });

    const [previewData, setPreviewData] = useState<InteractionData | null>(null);
    const [toast, setToast] = useState<{ msg: string; visible: boolean }>({ msg: '', visible: false });

    const hoveredDataRef = useRef<InteractionData | null>(null);
    const mousePosRef = useRef({ x: 0, y: 0 });

    useEffect(() => {
        const handleMouseMove = (e: MouseEvent) => {
            mousePosRef.current = { x: e.clientX, y: e.clientY };

            if (e.ctrlKey && hoveredDataRef.current) {
                setTooltipData(prev => ({
                    ...prev,
                    x: e.clientX,
                    y: e.clientY,
                    visible: true,
                    name: hoveredDataRef.current?.name || ''
                }));
            } else {
                setTooltipData(prev => ({ ...prev, visible: false }));
            }
        };

        const handleClick = (e: MouseEvent) => {
            // Match the HUD prompt: SHIFT + CLICK to copy
            // This provides a stronger "user gesture" context for browsers
            if (e.shiftKey && hoveredDataRef.current) {
                const name = hoveredDataRef.current.name;
                copyToClipboard(name).then(() => {
                    sfx.play('CLICK');
                    setToast({ msg: `DATA ACQUIRED: ${name}`, visible: true });
                    setTimeout(() => setToast(prev => ({ ...prev, visible: false })), 2000);
                }).catch(err => {
                    // Fail silently in debug but prevent crash
                    console.debug('Clipboard action failed:', err);
                });
            }
        };

        const handleKeyDown = (e: KeyboardEvent) => {
            if (e.key === 'Control' && hoveredDataRef.current) {
                setTooltipData({
                    name: hoveredDataRef.current.name,
                    x: mousePosRef.current.x,
                    y: mousePosRef.current.y,
                    visible: true
                });
            }
        };

        const handleKeyUp = (e: KeyboardEvent) => {
            if (e.key === 'Control') {
                setTooltipData(prev => ({ ...prev, visible: false }));
            }
        };

        const handleHoverChange = (e: CustomEvent) => {
            const data = e.detail as InteractionData | null;
            hoveredDataRef.current = data;
            setPreviewData(data);

            if (!data) {
                setTooltipData(prev => ({ ...prev, visible: false }));
            } else if (data && tooltipData.visible) {
                setTooltipData(prev => ({ ...prev, name: data.name }));
            }
        };

        window.addEventListener('mousemove', handleMouseMove);
        window.addEventListener('mousedown', handleClick); 
        window.addEventListener('keydown', handleKeyDown);
        window.addEventListener('keyup', handleKeyUp);
        window.addEventListener('interaction-hover', handleHoverChange as EventListener);

        return () => {
            window.removeEventListener('mousemove', handleMouseMove);
            window.removeEventListener('mousedown', handleClick);
            window.removeEventListener('keydown', handleKeyDown);
            window.removeEventListener('keyup', handleKeyUp);
            window.removeEventListener('interaction-hover', handleHoverChange as EventListener);
        };
    }, [tooltipData.visible]);

    return (
        <div className="pointer-events-none fixed inset-0 z-[9999]">

            {/* --- TOP PREVIEW HUD (TARGET LOCKED) --- */}
            <div className={`
                absolute top-4 left-1/2 -translate-x-1/2 
                transition-all duration-300 ease-out
                flex flex-col items-center gap-2
                ${previewData ? 'opacity-100 translate-y-0' : 'opacity-0 -translate-y-4'}
            `}>
                <div className="bg-black/90 border border-[#F2D019] p-1 shadow-[0_0_20px_rgba(242,208,25,0.2)] backdrop-blur-md flex items-center gap-3 pr-4">
                    <div className="w-16 h-16 border border-white/20 bg-[#111] overflow-hidden relative">
                        {previewData?.src ? (
                            <img 
                                src={previewData.src} 
                                className="w-full h-full object-contain object-center" 
                                alt="Preview" 
                            />
                        ) : (
                            <div className="w-full h-full flex items-center justify-center text-xs text-gray-600 font-mono">NO IMG</div>
                        )}
                        <div className="absolute inset-0 border border-[#F2D019]/30">
                            <div className="absolute top-1/2 left-0 w-full h-[1px] bg-[#F2D019]/30" />
                            <div className="absolute top-0 left-1/2 w-[1px] h-full bg-[#F2D019]/30" />
                        </div>
                    </div>

                    <div className="flex flex-col">
                        <span className="text-[10px] font-mono text-[#F2D019] tracking-widest animate-pulse">TARGET LOCKED</span>
                        <span className="font-['Teko'] text-2xl text-white uppercase tracking-wide leading-none max-w-[200px] truncate">
                            {previewData?.name}
                        </span>
                        <span className="text-[9px] font-mono text-gray-500 uppercase tracking-wider">
                            SHIFT + CLICK TO COPY
                        </span>
                    </div>
                </div>

                <div className="w-[1px] h-4 bg-gradient-to-b from-[#F2D019] to-transparent opacity-50" />
            </div>


            {/* --- MOUSE TOOLTIP (CONTROL) --- */}
            <div 
                className={`absolute transition-opacity duration-100 ease-out flex flex-col items-start gap-1 ${tooltipData.visible ? 'opacity-100' : 'opacity-0'}`}
                style={{ left: tooltipData.x + 20, top: tooltipData.y + 20 }}
            >
                <div className="absolute -top-3 -left-3 w-4 h-4 border-l-2 border-t-2 border-[#00F0FF]" />
                <div className="bg-black/90 border border-[#00F0FF] px-4 py-2 shadow-[0_0_15px_rgba(0,240,255,0.3)] backdrop-blur-md">
                    <div className="flex items-center gap-2 mb-1">
                        <div className="w-1.5 h-1.5 bg-[#00F0FF] animate-pulse rounded-full" />
                        <span className="text-[9px] font-['Roboto_Mono'] text-[#00F0FF] tracking-widest uppercase">
                            OBJECT IDENTIFIER
                        </span>
                    </div>
                    <span className="font-['Teko'] text-2xl text-white tracking-wide uppercase leading-none">
                        {tooltipData.name}
                    </span>
                </div>
            </div>

            {/* --- TOAST NOTIFICATION (SHIFT) --- */}
            <div className={`
                absolute bottom-24 left-1/2 -translate-x-1/2 
                bg-[#F2D019] text-black px-8 py-3 
                transform transition-all duration-300 cubic-bezier(0.175, 0.885, 0.32, 1.275)
                clip-path-polygon-[0_0,_100%_0,_95%_100%,_5%_100%]
                border-2 border-white shadow-[0_0_30px_rgba(242,208,25,0.5)]
                flex items-center gap-4
                ${toast.visible ? 'translate-y-0 opacity-100 scale-100' : 'translate-y-10 opacity-0 scale-90'}
            `}>
                <div className="w-6 h-6 border-2 border-black flex items-center justify-center animate-spin">
                    <div className="w-2 h-2 bg-black" />
                </div>
                <div>
                    <div className="font-['Teko'] text-3xl font-bold leading-none tracking-widest">COPIED</div>
                    <div className="font-mono text-[10px] font-bold uppercase tracking-[0.2em] opacity-80">{toast.msg}</div>
                </div>
            </div>
        </div>
    );
};

// --- PROVIDER ---
export const InteractionProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    const setHoveredItem = (data: InteractionData | null) => {
        window.dispatchEvent(new CustomEvent('interaction-hover', { detail: data }));
    };

    return (
        <InteractionContext.Provider value={{ setHoveredItem }}>
            {children}
            <InteractionUI />
        </InteractionContext.Provider>
    );
};

