import React, { useEffect, useRef } from 'react';
import * as THREE from 'three';

// --- CONFIGURACIÓN DE TELA PREMIUM ---
const config = {
    windForce: 0.18,
    baseColor: new THREE.Color(0x0a0a0c), // Negro carbón profundo
};

// --- SHADER: TOP-PINNED CARBON SILK ---
const vertexShader = `
uniform float uTime;
uniform float uWindStrength;

varying vec2 vUv;
varying vec3 vNormal;
varying float vDisplacement;

void main() {
    vUv = uv;
    vec3 pos = position;

    // FÍSICA: Pinneado superior (uv.y=1 es estático)
    // El exponente 2.0 crea una transición más firme cerca del soporte
    float influence = pow(1.0 - uv.y, 2.0); 

    // Movimiento suave y orgánico
    float noise = sin(pos.x * 1.8 + uTime * 1.5) * cos(pos.y * 0.8 + uTime * 2.2);
    float ripple = sin(uTime * 4.0 + pos.y * 10.0 + pos.x * 5.0) * 0.05;

    float displacement = (noise + ripple) * uWindStrength * influence;

    pos.z += displacement;

    // Efecto gravitacional sutil
    pos.y += abs(displacement) * 0.08 * influence;
    pos.x += sin(uTime * 0.5) * 0.02 * influence;

    vNormal = normalize(normalMatrix * normal);
    vDisplacement = displacement;

    gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
}
`;

const fragmentShader = `
uniform sampler2D uTexture;
uniform vec3 uBaseColor;
uniform float uTime;

varying vec2 vUv;
varying vec3 vNormal;
varying float vDisplacement;

void main() {
    vec4 mapTex = texture2D(uTexture, vUv);

    // 1. CARBON FIBER WEAVE (Micro-patrón de alta gama)
    float scale = 180.0;
    vec2 grid = fract(vUv * scale);
    float pattern = step(0.5, grid.x) == step(0.5, grid.y) ? 0.9 : 1.0;

    // 2. MATERIAL Y COLORES
    vec3 goldColor = vec3(1.0, 0.85, 0.2); // Oro brillante
    float isGold = smoothstep(0.1, 0.5, mapTex.r); // Canal rojo define el bordado

    vec3 albedo = mix(uBaseColor, goldColor, isGold);

    // 3. ILUMINACIÓN AVANZADA
    vec3 lightDir = normalize(vec3(0.5, 0.8, 1.0));
    vec3 viewDir = normalize(vec3(0.0, 0.0, 1.0));
    vec3 normal = normalize(vNormal + vec3(0.0, 0.0, vDisplacement * 0.7));

    float diff = max(dot(normal, lightDir), 0.0);

    // Brillo metálico para el oro (Anisotropía simulada)
    float spec = pow(max(dot(reflect(-lightDir, normal), viewDir), 0.0), 32.0);
    float goldSpec = isGold * spec * 2.0;

    // Sombras ambientales
    float ao = mix(0.4, 1.0, smoothstep(-0.4, 0.4, vDisplacement));

    // Brillo sutil en los bordes de la tela (Fresnel)
    float fresnel = pow(1.0 - max(dot(normal, viewDir), 0.0), 4.0);
    vec3 sheen = mix(vec3(0.1), goldColor, isGold) * fresnel * 0.6;

    vec3 finalColor = (albedo * (diff + 0.2) * pattern * ao) + goldSpec + sheen;

    // Glitch sutil en el canal de salida
    float scanline = sin(vUv.y * 500.0 + uTime * 10.0) * 0.02;
    finalColor += scanline * isGold;

    gl_FragColor = vec4(finalColor, 1.0);
}
`;

// GENERADOR DE DISEÑO "CARBON & GOLD"
const createTacticalMapTexture = () => {
    const canvas = document.createElement('canvas');
    canvas.width = 512;
    canvas.height = 768;
    const ctx = canvas.getContext('2d');

    if (ctx) {
        // Fondo Base
        ctx.fillStyle = '#0a0a0c';
        ctx.fillRect(0, 0, 512, 768);

        // Estilo de trazo para el oro
        ctx.strokeStyle = '#F2D019';
        ctx.fillStyle = '#F2D019';
        ctx.shadowColor = '#F2D019';
        ctx.shadowBlur = 4;

        // MARCO SUPERIOR TÉCNICO
        ctx.fillRect(0, 0, 512, 6);
        ctx.fillRect(40, 10, 432, 2);

        // LOGO CENTRAL "S07"
        ctx.textAlign = 'center';
        ctx.font = '900 110px "Teko"';
        ctx.fillText('07', 256, 400);

        // Circuitos decorativos (Grabado en oro)
        ctx.lineWidth = 1.5;
        ctx.beginPath();
        for(let i=0; i<8; i++) {
            ctx.moveTo(100, 100 + i*80); ctx.lineTo(150, 150 + i*80);
            ctx.moveTo(412, 100 + i*80); ctx.lineTo(362, 150 + i*80);
        }
        ctx.stroke();

        // HUD Inferior
        ctx.font = 'bold 24px "Roboto Mono"';
        ctx.fillText('OPERATIONAL DATA // S07', 256, 680);

        // Elementos de medición
        ctx.lineWidth = 4;
        ctx.strokeRect(60, 60, 392, 648);

        // X central
        ctx.beginPath();
        ctx.moveTo(230, 384); ctx.lineTo(282, 384);
        ctx.moveTo(256, 358); ctx.lineTo(256, 410);
        ctx.stroke();

        // Texto Classified
        ctx.font = '900 35px "Teko"';
        ctx.globalAlpha = 0.5;
        ctx.fillText('CLASSIFIED MATERIAL', 256, 80);
    }

    const texture = new THREE.CanvasTexture(canvas);
    texture.colorSpace = THREE.SRGBColorSpace;
    texture.anisotropy = 16;
    return { texture };
};

export const Flag: React.FC = () => {
    const containerRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        if (!containerRef.current) return;

        const width = containerRef.current.clientWidth;
        const height = containerRef.current.clientHeight;

        const scene = new THREE.Scene();
        const camera = new THREE.PerspectiveCamera(38, width / height, 0.1, 100);
        camera.position.set(0, 0, 5.0); 

        const renderer = new THREE.WebGLRenderer({ alpha: true, antialias: true });
        renderer.setSize(width, height);
        renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
        containerRef.current.appendChild(renderer.domElement);

        const { texture } = createTacticalMapTexture();
        texture.needsUpdate = true;

        const material = new THREE.ShaderMaterial({
            vertexShader: vertexShader,
            fragmentShader: fragmentShader,
            uniforms: {
                uTexture: { value: texture },
                uTime: { value: 0 },
                uWindStrength: { value: config.windForce },
                uBaseColor: { value: config.baseColor }
            },
            side: THREE.DoubleSide,
            transparent: true,
        });

        const geometry = new THREE.PlaneGeometry(1.9, 2.7, 50, 70);
        const mesh = new THREE.Mesh(geometry, material);
        scene.add(mesh);

        const clock = new THREE.Clock();
        let animationId: number;

        const animate = () => {
            animationId = requestAnimationFrame(animate);
            material.uniforms.uTime.value = clock.getElapsedTime();
            renderer.render(scene, camera);
        };
        animate();

        const handleResize = () => {
            if (!containerRef.current) return;
            const newW = containerRef.current.clientWidth;
            const newH = containerRef.current.clientHeight;
            camera.aspect = newW / newH;
            camera.updateProjectionMatrix();
            renderer.setSize(newW, newH);
        };
        window.addEventListener('resize', handleResize);

        return () => {
            window.removeEventListener('resize', handleResize);
            cancelAnimationFrame(animationId);
            renderer.dispose();
            geometry.dispose();
            material.dispose();
            texture.dispose();
            if (containerRef.current) containerRef.current.innerHTML = '';
        };
    }, []);

    return <div ref={containerRef} className="w-full h-full pointer-events-none" />;
};

