import React, { useEffect, useRef } from 'react';
import * as THREE from 'three';

// --- CONFIGURACIÓN DE TELA BORDERLANDS ---
const config = {
    windForce: 0.22, // Un poco más rígida/pesada
    baseColor: new THREE.Color(0x1a1a1a), // Gris oscuro sucio
};

// --- SHADER: GRITTY OLD CLOTH ---
const vertexShader = `
uniform float uTime;
uniform float uWindStrength;

varying vec2 vUv;
varying vec3 vNormal;
varying float vDisplacement;

void main() {
    vUv = uv;
    vec3 pos = position;

    // Pinneado superior con resistencia
    float influence = pow(1.0 - uv.y, 1.8); 

    // Movimiento más pesado y espasmódico
    float noise = sin(pos.x * 2.0 + uTime * 1.2) * cos(pos.y * 1.0 + uTime * 1.8);
    float folds = sin(uTime * 2.5 + pos.y * 8.0) * 0.1;

    float displacement = (noise + folds) * uWindStrength * influence;
    pos.z += displacement;

    // Deformación física de tela vieja
    pos.y += abs(displacement) * 0.12 * influence;

    vNormal = normalize(normalMatrix * normal);
    vDisplacement = displacement;

    gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
}
`;

const fragmentShader = `
uniform sampler2D uTexture;
uniform vec3 uBaseColor;
uniform float uTime;

varying vec2 vUv;
varying vec3 vNormal;
varying float vDisplacement;

// Función de ruido simple para suciedad
float hash(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123); }
float noise(vec2 p) {
    vec2 i = floor(p); vec2 f = fract(p);
    f = f*f*(3.0-2.0*f);
    return mix(mix(hash(i + vec2(0,0)), hash(i + vec2(1,0)), f.x),
               mix(hash(i + vec2(0,1)), hash(i + vec2(1,1)), f.x), f.y);
}

void main() {
    vec4 mapTex = texture2D(uTexture, vUv);

    // 1. TEXTURA DE TELA VIEJA (Grunge)
    float grunge = noise(vUv * 50.0 + 10.0) * 0.3;
    float dirt = noise(vUv * 5.0) * 0.5;

    // 2. MATERIAL ESTILO CEL-SHADED
    vec3 stencilColor = mapTex.rgb;
    float isLogo = mapTex.a; // Usamos el alpha del canvas para el stencil

    vec3 albedo = mix(uBaseColor - grunge, stencilColor, isLogo);

    // 3. ILUMINACIÓN "INKED" (Estilo Comic/Borderlands)
    vec3 lightDir = normalize(vec3(0.5, 0.8, 1.0));
    vec3 normal = normalize(vNormal + vec3(0.0, 0.0, vDisplacement * 0.8));
    float diff = max(dot(normal, lightDir), 0.0);

    // Sombras agresivas (Cel-shading)
    float celShadow = smoothstep(0.3, 0.35, diff);
    vec3 litColor = albedo * mix(0.4, 1.2, celShadow);

    // Manchas de desgaste y bordes "sucios"
    float wear = smoothstep(0.4, 0.6, noise(vUv * 20.0));
    litColor *= (1.0 - wear * 0.2);

    gl_FragColor = vec4(litColor, 1.0);
}
`;

// GENERADOR DE DISEÑO "VAULT STENCIL"
const createBorderlandsTexture = () => {
    const canvas = document.createElement('canvas');
    canvas.width = 512;
    canvas.height = 768;
    const ctx = canvas.getContext('2d');

    if (ctx) {
        // Fondo Base (Transparente para que el shader maneje el color de la tela)
        ctx.clearRect(0, 0, 512, 768);

        // Estilo de "Pintura en Spray" / Stencil
        const accentColor = '#F2D019'; // Amarillo Borderlands
        ctx.fillStyle = accentColor;
        ctx.strokeStyle = '#000000'; // Bordes entintados

        // 1. MANCHAS DE FONDO (Spray splatter)
        ctx.globalAlpha = 0.3;
        for(let i=0; i<20; i++) {
            ctx.beginPath();
            ctx.arc(Math.random()*512, Math.random()*768, Math.random()*40, 0, Math.PI*2);
            ctx.fill();
        }
        ctx.globalAlpha = 1.0;

        // 2. LOGO CENTRAL STYLIZED "U" (Tipo Vault)
        ctx.lineWidth = 12;
        ctx.lineJoin = 'miter';

        // Círculo exterior incompleto
        ctx.beginPath();
        ctx.arc(256, 384, 150, 0.2 * Math.PI, 1.3 * Math.PI);
        ctx.stroke();

        // Icono "U" / Pico
        ctx.beginPath();
        ctx.moveTo(256, 250);
        ctx.lineTo(350, 480);
        ctx.lineTo(162, 480);
        ctx.closePath();
        ctx.fill();
        ctx.stroke();

        // 3. TEXTO "BANDIT STYLE"
        ctx.textAlign = 'center';
        ctx.font = '900 80px "Teko"';
        ctx.save();
        ctx.translate(256, 150);
        ctx.rotate(-0.05);
        ctx.fillText('UNIBELANDS', 0, 0);
        ctx.restore();

        // 4. MARCAS DE "RECUENTO" (Kills/Projects)
        ctx.font = '900 60px "Teko"';
        ctx.fillText('////', 100, 650);
        ctx.fillText('//', 100, 710);

        // 5. EFECTO DE DESGASTE EN CANVAS (Holes/Fraying)
        ctx.globalCompositeOperation = 'destination-out';
        for(let i=0; i<30; i++) {
            ctx.beginPath();
            ctx.arc(Math.random()*512, Math.random()*768, Math.random()*15, 0, Math.PI*2);
            ctx.fill();
        }
    }

    const texture = new THREE.CanvasTexture(canvas);
    texture.colorSpace = THREE.SRGBColorSpace;
    return { texture };
};

export const Flag: React.FC = () => {
    const containerRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        if (!containerRef.current) return;

        const width = containerRef.current.clientWidth;
        const height = containerRef.current.clientHeight;

        const scene = new THREE.Scene();
        const camera = new THREE.PerspectiveCamera(38, width / height, 0.1, 100);
        camera.position.set(0, 0, 5.0); 

        const renderer = new THREE.WebGLRenderer({ alpha: true, antialias: true });
        renderer.setSize(width, height);
        renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
        containerRef.current.appendChild(renderer.domElement);

        const { texture } = createBorderlandsTexture();
        texture.needsUpdate = true;

        const material = new THREE.ShaderMaterial({
            vertexShader: vertexShader,
            fragmentShader: fragmentShader,
            uniforms: {
                uTexture: { value: texture },
                uTime: { value: 0 },
                uWindStrength: { value: config.windForce },
                uBaseColor: { value: config.baseColor }
            },
            side: THREE.DoubleSide,
            transparent: true,
        });

        // 15% MÁS PEQUEÑA: 1.9 * 0.85 = 1.615 | 2.7 * 0.85 = 2.295
        const geometry = new THREE.PlaneGeometry(1.61, 2.29, 40, 60);
        const mesh = new THREE.Mesh(geometry, material);
        scene.add(mesh);

        const clock = new THREE.Clock();
        let animationId: number;

        const animate = () => {
            animationId = requestAnimationFrame(animate);
            material.uniforms.uTime.value = clock.getElapsedTime();
            renderer.render(scene, camera);
        };
        animate();

        const handleResize = () => {
            if (!containerRef.current) return;
            const newW = containerRef.current.clientWidth;
            const newH = containerRef.current.clientHeight;
            camera.aspect = newW / newH;
            camera.updateProjectionMatrix();
            renderer.setSize(newW, newH);
        };
        window.addEventListener('resize', handleResize);

        return () => {
            window.removeEventListener('resize', handleResize);
            cancelAnimationFrame(animationId);
            renderer.dispose();
            geometry.dispose();
            material.dispose();
            texture.dispose();
            if (containerRef.current) containerRef.current.innerHTML = '';
        };
    }, []);

    return <div ref={containerRef} className="w-full h-full pointer-events-none" />;
};

