import React, { useEffect, useRef } from 'react';
import * as THREE from 'three';

// --- CONFIGURACIÓN TELA AVANZADA ---
const config = {
    windForce: 0.28, 
    baseColor: new THREE.Color(0x222222), // Tela gris carbón quemada
};

// --- SHADER: TORN OLD CLOTH WITH MULTI-WAVE WIND ---
const vertexShader = `
uniform float uTime;
uniform float uWindStrength;

varying vec2 vUv;
varying vec3 vNormal;
varying float vDisplacement;

void main() {
    vUv = uv;
    vec3 pos = position;

    // Pinneado superior suave (la bandera cuelga de la barra superior)
    float pinWeight = pow(1.0 - uv.y, 1.5); 

    // Multi-Layered Wind (Ondas sinusoidales superpuestas para caos natural)
    float w1 = sin(pos.x * 1.5 + uTime * 2.0) * cos(pos.y * 1.0 + uTime * 0.5);
    float w2 = sin(pos.y * 3.0 + uTime * 3.5) * 0.4;
    float w3 = sin(uTime * 5.0 + (pos.x + pos.y) * 2.0) * 0.15;

    float noise = (w1 + w2 + w3);
    float displacement = noise * uWindStrength * pinWeight;

    pos.z += displacement;

    // Efecto de "tirón" hacia arriba por el viento
    pos.y += abs(displacement) * 0.15 * pinWeight;
    // Efecto de encogimiento lateral
    pos.x -= abs(displacement) * 0.05 * pinWeight;

    vNormal = normalize(normalMatrix * normal);
    vDisplacement = displacement;

    gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
}
`;

const fragmentShader = `
uniform sampler2D uTexture;
uniform vec3 uBaseColor;
uniform float uTime;

varying vec2 vUv;
varying vec3 vNormal;
varying float vDisplacement;

// Función de ruido procedural
float hash(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123); }
float noise(vec2 p) {
    vec2 i = floor(p); vec2 f = fract(p);
    f = f*f*(3.0-2.0*f);
    return mix(mix(hash(i + vec2(0,0)), hash(i + vec2(1,0)), f.x),
               mix(hash(i + vec2(0,1)), hash(i + vec2(1,1)), f.x), f.y);
}

void main() {
    // 1. GENERAR MAPA DE AGUJEROS Y DESGASTE (FRAYING)
    float edgeNoise = noise(vUv * 45.0 + uTime * 0.05);
    float holeNoise = noise(vUv * 15.0);

    // Calcular máscara de borde deshilachado (izq, der, abajo)
    float borderMask = 1.0;
    float distToLeft = vUv.x;
    float distToRight = 1.0 - vUv.x;
    float distToBottom = vUv.y;

    // El deshilachado solo ocurre abajo y en los lados, no en el soporte (y > 0.95)
    float frayAmount = 0.06 + edgeNoise * 0.08;
    if (vUv.y < 0.96) {
        if (distToLeft < frayAmount || distToRight < frayAmount || distToBottom < frayAmount) {
            discard; // Cortar el pixel para crear el borde roto
        }
    }

    // Agujeros aleatorios en el centro
    if (holeNoise > 0.88 && vUv.y < 0.85) {
        discard;
    }

    vec4 mapTex = texture2D(uTexture, vUv);

    // 2. TEXTURA DE TELA (Micro-grano)
    float clothGrain = noise(vUv * 400.0) * 0.15;
    float dirt = noise(vUv * 8.0) * 0.4;

    vec3 albedo = mix(uBaseColor, mapTex.rgb, mapTex.a);
    albedo -= clothGrain;
    albedo -= dirt * 0.2;

    // 3. ILUMINACIÓN "CEL-SHADED" INKED
    vec3 lightDir = normalize(vec3(0.5, 0.8, 1.0));
    vec3 n = normalize(vNormal + vec3(0.0, 0.0, vDisplacement * 0.5));
    float diff = max(dot(n, lightDir), 0.0);

    // Sombras duras estilo comic
    float cel = smoothstep(0.35, 0.38, diff);
    vec3 finalColor = albedo * mix(0.4, 1.1, cel);

    // Resaltar bordes rotos con un tono más claro (hilos sueltos)
    float edgeHighlight = smoothstep(frayAmount, frayAmount + 0.02, min(distToLeft, min(distToRight, distToBottom)));
    finalColor = mix(finalColor * 1.3, finalColor, edgeHighlight);

    gl_FragColor = vec4(finalColor, 1.0);
}
`;

// GENERADOR DE DISEÑO "ULTIMATE VAULT BANDIT"
const createBorderlandsTexture = () => {
    const canvas = document.createElement('canvas');
    canvas.width = 512;
    canvas.height = 768;
    const ctx = canvas.getContext('2d');

    if (ctx) {
        ctx.clearRect(0, 0, 512, 768);

        const yellow = '#F2D019';
        const red = '#b81d13'; 
        const black = '#000000';

        // 1. MANCHAS DE SANGRE / PINTURA (Bandit Splatters)
        ctx.fillStyle = red;
        ctx.globalAlpha = 0.6;
        for(let i=0; i<8; i++) {
            ctx.beginPath();
            ctx.arc(Math.random()*512, Math.random()*768, Math.random()*60, 0, Math.PI*2);
            ctx.fill();
        }
        ctx.globalAlpha = 1.0;

        // 2. LOGO VAULT CENTRAL (Estilo Borderlands icónico)
        ctx.strokeStyle = black;
        ctx.lineWidth = 15;

        // El arco de la cámara
        ctx.beginPath();
        ctx.arc(256, 384, 160, 0.2 * Math.PI, 1.25 * Math.PI);
        ctx.stroke();

        // El pico (V) interior
        ctx.fillStyle = yellow;
        ctx.beginPath();
        ctx.moveTo(256, 240);
        ctx.lineTo(360, 480);
        ctx.lineTo(152, 480);
        ctx.closePath();
        ctx.fill();
        ctx.stroke();

        // 3. DETALLES DE "INKING" (Rayas de comic)
        ctx.strokeStyle = black;
        ctx.lineWidth = 4;
        for(let i=0; i<30; i++) {
            ctx.beginPath();
            const x = Math.random() * 512;
            const y = Math.random() * 768;
            ctx.moveTo(x, y);
            ctx.lineTo(x + 20, y + 10);
            ctx.stroke();
        }

        // 4. TEXTO AGRESIVO
        ctx.textAlign = 'center';
        ctx.font = '900 70px "Teko"';
        ctx.fillStyle = black;

        ctx.save();
        ctx.translate(256, 160);
        ctx.rotate(-0.1);
        ctx.fillText('DO NOT ENTER', 0, 0);
        ctx.restore();

        ctx.fillStyle = yellow;
        ctx.font = '900 90px "Teko"';
        ctx.fillText('PANDORA', 256, 680);

        // Cruzar el texto con rojo
        ctx.strokeStyle = red;
        ctx.lineWidth = 8;
        ctx.beginPath();
        ctx.moveTo(100, 650);
        ctx.lineTo(412, 650);
        ctx.stroke();

        // Marcas de recuento
        ctx.font = '900 50px "Teko"';
        ctx.fillStyle = red;
        ctx.fillText('IIII-II', 100, 100);
    }

    const texture = new THREE.CanvasTexture(canvas);
    texture.colorSpace = THREE.SRGBColorSpace;
    return { texture };
};

