interface StackScreenProps {
    onClose: () => void;
}

export const StackScreen: React.FC<StackScreenProps> = ({ onClose }) => {
    const [viewMode, setViewMode] = useState<ViewMode>('RESOURCES');
    const [activeCategory, setActiveCategory] = useState<ItemCategory>('ALL');
    const [selectedItem, setSelectedItem] = useState<any>(STACK_DATABASE[0]);
    const [previewItem, setPreviewItem] = useState<any>(null);
    const [isClosing, setIsClosing] = useState(false);
    const [animateCard, setAnimateCard] = useState(false);

    // Dynamic Theme Colors
    const themeColor = viewMode === 'WEAPONS' ? '#00F0FF' : '#F2D019';
    const themeText = viewMode === 'WEAPONS' ? 'text-[#00F0FF]' : 'text-[#F2D019]';

    useEffect(() => {
        sfx.play('EQUIP');
    }, []);

    const handleClose = () => {
        setIsClosing(true);
        sfx.play('CLICK');
        setTimeout(onClose, 300); 
    };

    const handleSelect = (item: any) => {
        if (item.id === selectedItem.id) return;
        sfx.play('EQUIP');
        setSelectedItem(item);
        setAnimateCard(true);
        setTimeout(() => setAnimateCard(false), 300);
    };

    const handleHover = (item: any | null) => {
        setPreviewItem(item);
        if (item && item.id !== selectedItem.id) sfx.play('HOVER'); 
    };

    const handleModeSwitch = (mode: ViewMode) => {
        if (viewMode === mode) return;
        sfx.play(mode === 'RESOURCES' ? 'CLICK' : 'EQUIP');
        setViewMode(mode);
        setSelectedItem(mode === 'WEAPONS' ? WEAPONS_DATABASE[0] : STACK_DATABASE[0]);
        setPreviewItem(null);
    };

    const itemToDisplay = previewItem || selectedItem;

    return (
        <div className={`
            fixed inset-0 z-[200] flex flex-col items-center
            bg-[#050505] overflow-hidden select-none
            ${isClosing ? 'animate-out fade-out duration-300' : 'animate-stack-entry'}
        `}>

            {/* GLOBAL BACKGROUND DOT PATTERN (ANIMATED) */}
            <div className="absolute inset-0 pointer-events-none z-0 opacity-20 animate-bg-pan" 
                 style={{ 
                     backgroundImage: 'radial-gradient(#555 3px, transparent 3px)', 
                     backgroundSize: '40px 40px' 
                 }} 
            />

            {/* HEADER (STAGGER 1) */}
            <div className="relative w-full max-w-[1800px] mt-6 mb-4 z-50 flex flex-col md:flex-row items-center justify-between px-6 gap-4 shrink-0 animate-fade-up delay-100">

                <div className="flex items-stretch h-14 w-full md:w-auto">
                    {/* Botón SALIR - Unified with skewed design */}
                    <button 
                        onClick={handleClose} 
                        className="relative flex items-center justify-center px-10 h-full bg-[#ef4444] text-black hover:bg-white transition-all transform -skew-x-[20deg] border-2 border-black z-30 shadow-lg group"
                    >
                        <div className="flex items-center gap-2 transform skew-x-[20deg]">
                            <Icons.Close className="w-5 h-5 transition-transform group-hover:rotate-90" />
                            <span className="font-['Teko'] text-2xl font-bold tracking-widest pt-1">SALIR</span>
                        </div>
                    </button>

                    {/* Botón SOFTWARE */}
                    <button onClick={() => handleModeSwitch('RESOURCES')} 
                        className={`
                            relative flex items-center justify-center px-12 h-full -ml-2 transform -skew-x-[20deg] transition-all border-2 border-black 
                            ${viewMode === 'RESOURCES' 
                                ? 'bg-[#F2D019] text-black z-20 outline outline-4 outline-white outline-offset-[-4px]' 
                                : 'bg-[#18181b] text-gray-500 hover:text-white z-10'
                            }
                        `}>
                        <span className="font-['Teko'] text-2xl font-bold tracking-widest pt-1 transform skew-x-[20deg]">SOFTWARE</span>
                    </button>

                    {/* Botón ARMAS */}
                    <button onClick={() => handleModeSwitch('WEAPONS')} 
                        className={`
                            relative flex items-center justify-center px-12 h-full -ml-2 transform -skew-x-[20deg] transition-all border-2 border-black
                            ${viewMode === 'WEAPONS' 
                                ? 'bg-[#3b82f6] text-white z-20 outline outline-4 outline-white outline-offset-[-4px]' 
                                : 'bg-[#18181b] text-gray-500 hover:text-white z-10'
                            }
                        `}>
                        <span className="font-['Teko'] text-2xl font-bold tracking-widest pt-1 transform skew-x-[20deg]">ARMAS</span>
                    </button>
                </div>

                <div className="flex flex-col items-end transform -skew-x-[10deg] border-r-4 border-white pr-4 self-end md:self-auto">
                    <h1 className="font-['Teko'] text-5xl font-bold text-white leading-none tracking-wider italic uppercase">SYSTEM_DATABASE</h1>
                    <span className={`font-mono text-[10px] tracking-[0.3em] font-bold ${themeText}`}>
                        {viewMode === 'WEAPONS' ? 'ARSENAL_LOADOUT' : 'SOFTWARE_INVENTORY'}
                    </span>
                </div>
            </div>

            {/* MAIN CONTENT AREA */}
            <div className="relative w-full max-w-[1800px] flex-grow flex flex-col lg:flex-row gap-12 p-6 z-10 overflow-hidden h-full pb-8">

                {/* GRID SECTION (STAGGER 2) */}
                <div className="w-full lg:w-[65%] h-full flex flex-col relative rounded-xl overflow-hidden bg-black/40 border border-white/10 backdrop-blur-sm animate-fade-up delay-200">
                    <InventoryGrid 
                        viewMode={viewMode} 
                        activeCategory={activeCategory} 
                        onCategoryChange={setActiveCategory} 
                        selectedItem={selectedItem} 
                        onSelect={handleSelect} 
                        onHover={handleHover} 
                    />
                </div>

                {/* INSPECTOR SECTION (STAGGER 3) */}
                <div className="w-full lg:w-[35%] h-full overflow-hidden flex flex-col relative pl-4 animate-fade-up delay-300">
                    <InspectorPanel 
                        selectedItem={itemToDisplay} 
                        animateCard={animateCard} 
                        themeColor={themeColor}
                    />
                </div>
            </div>
        </div>
    );
};

import React from 'react';
import { StackItem, WeaponConfig, isWeapon } from '../types';
import { RARITY_CONFIG, ExtendedStackItem } from '../data';
