interface InspectorPanelProps {
    selectedItem: StackItem | WeaponConfig;
    animateCard: boolean;
    themeColor?: string;
}

export const InspectorPanel: React.FC<InspectorPanelProps> = React.memo(({ selectedItem, animateCard, themeColor = '#F2D019' }) => {

    const accentColor = themeColor; 
    const extendedItem = !isWeapon(selectedItem) ? (selectedItem as ExtendedStackItem) : null;
    const IconComponent = extendedItem?.iconKey ? SkillIcons[extendedItem.iconKey] : null;
    const has3D = ['3dsmax', 'blender', 'figma', 'xd', 'ae', 'premiere', 'ai', 'sub_painter', 'sub_designer', 'powershell', 'id', 'ps', 'affinity', 'audition'].includes(selectedItem.id);

    const skillLevel = !isWeapon(selectedItem) ? Math.min(selectedItem.level, 100) : 100;
    const expLevel = Math.min(skillLevel * 0.9, 100);

    return (
        <div className={`
            w-full h-full flex flex-col relative overflow-hidden
            transition-all duration-300
            ${animateCard ? 'opacity-50 scale-[0.98]' : 'opacity-100 scale-100'}
        `}>
            {/* Header info floating above - FIXED HEIGHT */}
            <div className="h-6 mb-2 flex items-center">
                <span className="bg-[#333] text-white px-2 py-1 text-[10px] font-bold uppercase tracking-widest">
                    {isWeapon(selectedItem) ? 'ADOBE // WEAPON' : `${selectedItem.manufacturer} // ${selectedItem.category}`}
                </span>
            </div>

            {/* TITLE CONTAINER - FIXED HEIGHT TO PREVENT SHIFT */}
            <div className="h-24 md:h-32 flex items-center mb-4">
                <h2 className="font-['Teko'] text-6xl md:text-8xl font-bold uppercase leading-[0.8] text-white tracking-wide drop-shadow-[4px_4px_0px_#000] line-clamp-2">
                    {selectedItem.name}
                </h2>
            </div>

            {/* 1. VISUAL (Transparent) - FIXED HEIGHT */}
            <div className="h-[35%] w-full relative flex items-center justify-center mb-6 shrink-0">
                {/* Subtle glow behind visual */}
                <div className="absolute inset-0 bg-radial-gradient from-white/10 to-transparent opacity-30" />

                <div className="relative w-full h-full flex items-center justify-center">
                    {has3D ? (
                        <div className="w-full h-full relative z-20 scale-125">
                            <Visualizer3D itemId={selectedItem.id} />
                        </div>
                    ) : isWeapon(selectedItem) ? (
                        <img 
                            src={selectedItem.image} 
                            alt={selectedItem.name} 
                            className="h-full w-auto object-contain drop-shadow-[0_10px_20px_rgba(0,0,0,0.8)]"
                        />
                    ) : (
                        <div className="relative w-full h-full flex items-center justify-center">
                            {IconComponent ? (
                                <IconComponent className="w-[60%] h-[60%] object-contain drop-shadow-[0_0_30px_rgba(255,255,255,0.15)] animate-float relative z-10" />
                            ) : (
                                <img 
                                    src={selectedItem.icon} 
                                    className="w-[50%] h-[50%] object-contain drop-shadow-[0_0_30px_rgba(255,255,255,0.2)] animate-float relative z-10"
                                    alt="Icon"
                                />
                            )}
                        </div>
                    )}
                </div>
            </div>

            {/* 2. INFO BODY (Integrated Text) */}
            <div className="flex-1 flex flex-col relative min-h-0">

                {/* Description - MIN HEIGHT FOR STABILITY */}
                <div className="min-h-[80px] mb-6">
                    <p className="font-['Roboto_Mono'] text-sm text-gray-400 leading-relaxed border-l-4 pl-6 border-white/30 max-w-lg italic">
                        {selectedItem.description}
                    </p>
                </div>

                {/* METRICS - FIXED SPACING */}
                <div className="mb-6 space-y-5 max-w-md">
                    <div className="flex justify-between items-end text-[#F2D019] border-b border-gray-700 pb-1 mb-2">
                        <span className="text-[10px] font-mono tracking-widest uppercase">PROFICIENCY METRICS</span>
                        <span className="font-bold text-sm">LVL {skillLevel}</span>
                    </div>

                    {/* Mastery Bar - THICK */}
                    <div className="group h-10">
                        <div className="flex justify-between text-[10px] font-bold text-gray-500 mb-1">
                            <span>MASTERY</span>
                            <span className="text-white">{skillLevel}%</span>
                        </div>
                        <div className="h-2 w-full bg-gray-900 border border-white/5">
                            <div className="h-full bg-white transition-all duration-1000 ease-out shadow-[0_0_10px_white]" 
                                 style={{ width: `${skillLevel}%` }} />
                        </div>
                    </div>

                    {/* Workflow Bar - THICK */}
                    <div className="group h-10">
                        <div className="flex justify-between text-[10px] font-bold text-gray-500 mb-1">
                            <span>WORKFLOW</span>
                            <span className="text-white">{Math.round(expLevel)}%</span>
                        </div>
                        <div className="h-2 w-full bg-gray-900 border border-white/5">
                            <div className="h-full transition-all duration-1000 ease-out delay-100 opacity-90" 
                                 style={{ width: `${expLevel}%`, backgroundColor: accentColor }} />
                        </div>
                    </div>
                </div>

                {/* Stats Footer (Integrated) - FIXED AT BOTTOM */}
                <div className="mt-auto grid grid-cols-2 gap-x-12 gap-y-4 max-w-md border-t-2 border-white/10 pt-6">
                    <StatRow label="POWER" value={selectedItem.stats.damage} color="white" />
                    <StatRow label="SPEED" value={selectedItem.stats.fireRate} color="#666" />
                </div>
            </div>
        </div>
    );
});

