                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>

                    <div className="absolute bottom-0 left-0 w-full h-16 bg-black/80 border-t border-[#F2D019] z-20 flex items-center justify-between px-12">
                        <div className="flex items-center gap-8">
                            <div className="flex flex-col">
                                <span className="text-[10px] font-mono text-gray-500 tracking-widest">SELECTED NODE</span>
                                <span className="font-['Teko'] text-3xl text-[#F2D019] leading-none">{mapNodes.find(n => n.id === activeNodeId)?.name}</span>
                            </div>
                            <div className="w-[1px] h-8 bg-[#333]" />
                            <div className="flex flex-col">
                                <span className="text-[10px] font-mono text-gray-500 tracking-widest">COORDINATES</span>
                                <span className="font-mono text-lg text-white leading-none">{mapNodes.find(n => n.id === activeNodeId)?.coords}</span>
                            </div>
                        </div>

                        <div className="flex items-center gap-2">
                            <div className="w-2 h-2 bg-green-500 rounded-full animate-pulse" />
                            <span className="font-['Teko'] text-xl text-green-500 tracking-wider">SYSTEM ONLINE</span>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

