import React, { useMemo, useState, useRef } from 'react';
import { StackItem, WeaponConfig, ViewMode, ItemCategory } from '../types';
import { STACK_DATABASE, WEAPONS_DATABASE } from '../data';
import { Icons } from '../assets/Icons';
import { CategoryTab } from './CategoryTab';
import { SkillIcons } from '../assets/SkillIcons';

interface InventoryGridProps {
    viewMode: ViewMode;
    activeCategory: ItemCategory;
    onCategoryChange: (cat: ItemCategory) => void;
    selectedItem: StackItem | WeaponConfig;
    onSelect: (item: any) => void;
    onHover: (item: any | null) => void;
}

export const InventoryGrid: React.FC<InventoryGridProps> = ({ 
    viewMode, 
    activeCategory, 
    onCategoryChange, 
    selectedItem, 
    onSelect,
    onHover
}) => {
    const weaponBarClip = 'polygon(0 0, 98% 0, 100% 40%, 100% 100%, 2% 100%, 0 60%)';
    const [quickViewId, setQuickViewId] = useState<string | null>(null);
    const quickViewTimerRef = useRef<number | null>(null);

    const filteredResources = useMemo(() => {
        if (activeCategory === 'ALL') return STACK_DATABASE;
        return STACK_DATABASE.filter(item => item.category === activeCategory);
    }, [activeCategory]);

    const getIconComponent = (item: any) => {
        if (item.iconKey && SkillIcons[item.iconKey]) return SkillIcons[item.iconKey];
        if (SkillIcons[item.id]) return SkillIcons[item.id];
        return null;
    };

    const handleMouseEnter = (item: any) => {
        onHover(item);
        // Start timer for INTERNAL QUICK VIEW (1.5 seconds)
        if (quickViewTimerRef.current) window.clearTimeout(quickViewTimerRef.current);
        quickViewTimerRef.current = window.setTimeout(() => {
            setQuickViewId(item.id);
        }, 1500); 
    };

    const handleMouseLeave = () => {
        onHover(null);
        setQuickViewId(null);
        if (quickViewTimerRef.current) {
            window.clearTimeout(quickViewTimerRef.current);
            // Fix: Changed hoverTimerRef to quickViewTimerRef as hoverTimerRef was undefined in this scope
            quickViewTimerRef.current = null;
        }
    };

    return (
        <div className="w-full h-full flex flex-col relative min-h-0">
            {viewMode === 'RESOURCES' ? (
                <>
                    {/* Tabs Bar with Videojuegos Added */}
                    <div className="flex flex-wrap items-center justify-center gap-2 p-3 md:p-5 border-b border-[#222] z-10 shrink-0 bg-[#080808]">
                        <CategoryTab label="TODO" icon={<Icons.All className="w-3 h-3 md:w-4 md:h-4" />} active={activeCategory === 'ALL'} onClick={() => onCategoryChange('ALL')} color="#F2D019" />
                        <CategoryTab label="GRÁFICO" icon={<Icons.Graphic className="w-3 h-3 md:w-4 md:h-4" />} active={activeCategory === 'GRAPHIC'} onClick={() => onCategoryChange('GRAPHIC')} color="#f472b6" />
                        <CategoryTab label="UI/UX" icon={<Icons.UIUX className="w-3 h-3 md:w-4 md:h-4" />} active={activeCategory === 'UI_UX'} onClick={() => onCategoryChange('UI_UX')} color="#c084fc" />
                        <CategoryTab label="VIDEOJUEGOS" icon={<Icons.Game className="w-3 h-3 md:w-4 md:h-4" />} active={activeCategory === 'GAME'} onClick={() => onCategoryChange('GAME')} color="#fb923c" />
                        <CategoryTab label="IA" icon={<Icons.AI className="w-3 h-3 md:w-4 md:h-4" />} active={activeCategory === 'AI'} onClick={() => onCategoryChange('AI')} color="#38bdf8" />
                    </div>

                    <div className="flex-grow overflow-y-auto p-4 md:p-8 sci-fi-scroll relative bg-[#050505]">
                        <div className="grid grid-cols-3 sm:grid-cols-4 md:grid-cols-5 gap-4 md:gap-6 content-start pb-4">
                            {filteredResources.map((item) => {
                                const isSelected = selectedItem.id === item.id;
                                const isQuickView = quickViewId === item.id;
                                const ToolIcon = getIconComponent(item);

                                return (
                                    <div 
                                        key={item.id} 
                                        onClick={() => onSelect(item)} 
                                        onMouseEnter={() => handleMouseEnter(item)} 
                                        onMouseLeave={handleMouseLeave} 
                                        className={`
                                            relative cursor-pointer aspect-square flex items-center justify-center rounded-xl 
                                            transition-all duration-300 group overflow-hidden
                                            ${isSelected 
                                                ? 'z-20 scale-105 border-4 border-white bg-black shadow-[0_0_30px_rgba(255,255,255,0.3)]' 
                                                : 'bg-[#111] border border-[#222] hover:bg-[#1a1a1a] hover:border-[#444] opacity-90 hover:opacity-100 hover:scale-105'
                                            }
                                        `}
                                    >
                                        {/* Internal content area */}
                                        <div className="relative w-full h-full flex items-center justify-center p-2">
                                            {/* Icon Layer: Fades out on Quick View */}
                                            <div className={`w-[50%] h-[50%] flex items-center justify-center transition-all duration-500 ${isQuickView ? 'opacity-10 scale-75 blur-sm' : 'opacity-100 scale-100'}`}>
                                                {ToolIcon ? (
                                                    <ToolIcon 
                                                        className={`w-full h-full object-contain transition-all duration-300 ${isSelected ? 'filter brightness-125' : 'filter brightness-100 opacity-80 group-hover:opacity-100'}`} 
                                                    />
                                                ) : (
                                                    <div className="w-4 h-4 bg-gray-600 rounded-sm" />
                                                )}
                                            </div>

                                            {/* Quick Stats Overlay Layer (Shown after 1.5s) */}
                                            <div className={`absolute inset-0 flex flex-col items-center justify-center p-4 transition-all duration-500 pointer-events-none ${isQuickView ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-4'}`}>
                                                <span className="font-['Teko'] text-xs text-[#F2D019] tracking-tighter mb-1 font-bold">INTERNAL_SPECS</span>
                                                <div className="w-full space-y-1.5">
                                                    <div className="h-1 w-full bg-white/10 overflow-hidden">
                                                        <div className="h-full bg-white" style={{ width: `${item.stats.damage}%` }} />
                                                    </div>
                                                    <div className="h-1 w-full bg-white/10 overflow-hidden">
                                                        <div className="h-full bg-[#F2D019]" style={{ width: `${item.stats.fireRate}%` }} />
                                                    </div>
                                                </div>
                                                <span className="mt-2 font-mono text-[8px] text-white/40 uppercase">LVL {item.level}</span>
                                            </div>
                                        </div>
                                    </div>
                                );
                            })}
                        </div>
                    </div>
                </>
            ) : (
                <div className="flex-grow p-4 md:p-6 overflow-y-auto sci-fi-scroll bg-[#050505]">
                    <div className="flex flex-col gap-3 md:gap-4">
                        {WEAPONS_DATABASE.map((weapon) => {
                            const isSelected = selectedItem.id === weapon.id;
                            return (
                                <div 
                                    key={weapon.id} 
                                    onClick={() => onSelect(weapon)} 
                                    onMouseEnter={() => onHover(weapon)} 
                                    onMouseLeave={() => onHover(null)}
                                    className={`
                                        relative h-24 md:h-32 w-full cursor-pointer flex items-center px-4 md:px-8 justify-between 
                                        transition-all duration-200 group overflow-hidden
                                        ${isSelected 
                                            ? 'bg-[#111] translate-x-2 border-4 border-white shadow-[0_0_30px_rgba(255,255,255,0.2)]' 
                                            : 'bg-[#0a0a0a] border-l-4 border-[#333] hover:bg-[#111] hover:border-white/50'
                                        }
                                    `}
                                    style={{ 
                                        clipPath: weaponBarClip, 
                                        boxShadow: isSelected ? 'inset 0 0 20px rgba(0,0,0,0.8)' : 'none'
                                    }}
                                >
                                    <div className="flex flex-col z-10">
                                        <span className={`font-['Teko'] text-2xl md:text-4xl font-bold uppercase leading-none ${isSelected ? 'text-white' : 'text-gray-500 group-hover:text-gray-300'}`}>
                                            {weapon.name}
                                        </span>
                                        <span className={`font-['Share_Tech_Mono'] text-[10px] md:text-sm ${isSelected ? 'text-[#00F0FF]' : 'text-gray-600'}`}>
                                            {weapon.subtitle}
                                        </span>
                                    </div>

                                    <div className="hidden sm:flex gap-2">
                                        {weapon.components.slice(0, 3).map(cid => (
                                            <div key={cid} className="w-8 h-8 md:w-10 md:h-10 p-1.5 flex items-center justify-center bg-black/50 rounded-full border border-white/10">
                                                {SkillIcons[cid] ? React.createElement(SkillIcons[cid], { className: "w-full h-full" }) : <div className="w-full h-full bg-gray-800 rounded-full" />}
                                            </div>
                                        ))}
                                    </div>

                                    {isSelected && <div className="absolute left-0 top-0 bottom-0 w-2 bg-white" />}
                                </div>
                            );
                        })}
                    </div>
                </div>
            )}
        </div>
    );
};

import React, { useState, useEffect, useRef } from 'react';
import { sfx } from '../../utils/SoundManager';
import { STACK_DATABASE, WEAPONS_DATABASE } from './data';
import { ViewMode, ItemCategory } from './types';
import { Icons } from './assets/Icons';

// Subcomponents
import { InventoryGrid } from './components/InventoryGrid';
import { InspectorPanel } from './components/InspectorPanel';

interface StackScreenProps {
    onClose: () => void;
}

export const StackScreen: React.FC<StackScreenProps> = ({ onClose }) => {
    const [viewMode, setViewMode] = useState<ViewMode>('RESOURCES');
    const [activeCategory, setActiveCategory] = useState<ItemCategory>('ALL');
    const [selectedItem, setSelectedItem] = useState<any>(STACK_DATABASE[0]);
    const [previewItem, setPreviewItem] = useState<any>(null);
    const [isClosing, setIsClosing] = useState(false);
    const [animateCard, setAnimateCard] = useState(false);

    const hoverTimerRef = useRef<number | null>(null);

    // Dynamic Theme Colors: Software = Yellow, Weapons = Blue
    const themeColor = viewMode === 'WEAPONS' ? '#00F0FF' : '#F2D019';
    const themeText = viewMode === 'WEAPONS' ? 'text-[#00F0FF]' : 'text-[#F2D019]';

    useEffect(() => {
        sfx.play('EQUIP');
        return () => {
            if (hoverTimerRef.current) window.clearTimeout(hoverTimerRef.current);
        };
    }, []);

    const handleClose = () => {
        setIsClosing(true);
        sfx.play('CLICK');
        setTimeout(onClose, 300); 
    };

    const handleSelect = (item: any) => {
        if (item.id === selectedItem.id) return;
        if (hoverTimerRef.current) window.clearTimeout(hoverTimerRef.current);

        sfx.play('EQUIP');
        setSelectedItem(item);
        setPreviewItem(null); 
        setAnimateCard(true);
        setTimeout(() => setAnimateCard(false), 300);
    };

    const handleHover = (item: any | null) => {
        if (hoverTimerRef.current) {
            window.clearTimeout(hoverTimerRef.current);
            hoverTimerRef.current = null;
        }

        if (item) {
            if (item.id !== selectedItem.id) {
                hoverTimerRef.current = window.setTimeout(() => {
                    setPreviewItem(item);
                    sfx.play('HOVER');
                }, 500); 
            }
        } else {
            setPreviewItem(null);
        }
    };

    const handleModeSwitch = (mode: ViewMode) => {
        if (viewMode === mode) return;
        sfx.play(mode === 'RESOURCES' ? 'CLICK' : 'EQUIP');
        setViewMode(mode);
        const defaultItem = mode === 'WEAPONS' ? WEAPONS_DATABASE[0] : STACK_DATABASE[0];
        setSelectedItem(defaultItem);
        setPreviewItem(null);
    };

    const itemToDisplay = previewItem || selectedItem;

    return (
        <div className={`
            fixed inset-0 z-[200] flex flex-col items-center
            bg-[#050505] overflow-hidden select-none
            ${isClosing ? 'animate-out fade-out duration-300' : 'animate-stack-entry'}
        `}>

            <div className="absolute inset-0 pointer-events-none z-0 opacity-20 animate-bg-pan" 
                 style={{ 
                     backgroundImage: 'radial-gradient(#555 3px, transparent 3px)', 
                     backgroundSize: '40px 40px' 
                 }} 
            />

            {/* HEADER AREA */}
            <div className="relative w-full max-w-[1800px] mt-6 mb-4 z-50 flex flex-col md:flex-row items-center justify-between px-6 gap-4 shrink-0 animate-fade-up delay-100">

                <div className="flex items-stretch h-14 w-full md:w-auto">
                    {/* Botón SALIR - Straight/Flush on left edge, skewed on right to match next button */}
                    <button 
                        onClick={handleClose} 
                        className="relative flex items-center justify-center px-12 h-full bg-[#ef4444] text-black hover:bg-white transition-all border-y-2 border-l-2 border-black z-30 shadow-lg group"
                        style={{ clipPath: 'polygon(0 0, 100% 0, 88% 100%, 0 100%)' }}
                    >
                        <div className="flex items-center gap-3 pr-4">
                            <Icons.Close className="w-5 h-5 transition-transform group-hover:rotate-90" />
                            <span className="font-['Teko'] text-3xl font-bold tracking-widest pt-1">SALIR</span>
                        </div>
                    </button>

                    {/* Botón SOFTWARE */}
                    <button onClick={() => handleModeSwitch('RESOURCES')} 
                        className={`
                            relative flex items-center justify-center px-14 h-full -ml-5 transform -skew-x-[15deg] transition-all border-2 border-black 
                            ${viewMode === 'RESOURCES' 
                                ? 'bg-[#F2D019] text-black z-20 outline outline-4 outline-white outline-offset-[-4px]' 
                                : 'bg-[#18181b] text-gray-500 hover:text-white z-10'
                            }
                        `}>
                        <span className="font-['Teko'] text-2xl font-bold tracking-widest pt-1 transform skew-x-[15deg]">SOFTWARE</span>
                    </button>

                    {/* Botón ARMAS */}
                    <button onClick={() => handleModeSwitch('WEAPONS')} 
                        className={`
                            relative flex items-center justify-center px-14 h-full -ml-3 transform -skew-x-[15deg] transition-all border-2 border-black
                            ${viewMode === 'WEAPONS' 
                                ? 'bg-[#3b82f6] text-white z-20 outline outline-4 outline-white outline-offset-[-4px]' 
                                : 'bg-[#18181b] text-gray-500 hover:text-white z-10'
                            }
                        `}>
                        <span className="font-['Teko'] text-2xl font-bold tracking-widest pt-1 transform skew-x-[15deg]">ARMAS</span>
                    </button>
                </div>

                <div className="flex flex-col items-end transform -skew-x-[10deg] border-r-4 border-white pr-4 self-end md:self-auto">
                    <h1 className="font-['Teko'] text-5xl font-bold text-white leading-none tracking-wider italic uppercase">SKILLS_INVENTORY</h1>
                    <span className={`font-mono text-[10px] tracking-[0.3em] font-bold ${themeText}`}>
                        {viewMode === 'WEAPONS' ? 'ARSENAL_LOADOUT' : 'SOFTWARE_INVENTORY'}
                    </span>
                </div>
            </div>

            <div className="relative w-full max-w-[1800px] flex-grow flex flex-col lg:flex-row gap-12 p-6 z-10 overflow-hidden h-full pb-8">
                <div className="w-full lg:w-[65%] h-full flex flex-col relative rounded-xl overflow-hidden bg-black/40 border border-white/10 backdrop-blur-sm animate-fade-up delay-200">
                    <InventoryGrid 
                        viewMode={viewMode} 
                        activeCategory={activeCategory} 
                        onCategoryChange={setActiveCategory} 
                        selectedItem={selectedItem} 
                        onSelect={handleSelect} 
                        onHover={handleHover} 
                    />
                </div>

                <div className="w-full lg:w-[35%] h-full overflow-hidden flex flex-col relative pl-4 animate-fade-up delay-300">
                    <InspectorPanel 
                        selectedItem={itemToDisplay} 
                        animateCard={animateCard} 
                        themeColor={themeColor}
                    />
                </div>
            </div>
        </div>
    );
};

