                        />
                    ) : (
                        <div className="relative w-full h-full flex items-center justify-center">
                            {IconComponent ? (
                                <IconComponent className="w-[60%] h-[60%] object-contain drop-shadow-[0_0_30px_rgba(255,255,255,0.15)] animate-float relative z-10" />
