                {/* Description - MIN HEIGHT FOR STABILITY */}
                <div className="min-h-[80px] mb-6">
                    <p className="font-['Roboto_Mono'] text-sm text-gray-400 leading-relaxed border-l-4 pl-6 border-white/30 max-w-lg italic">
                        {selectedItem.description}
                    </p>
                </div>

                {/* METRICS - FIXED SPACING */}
                <div className="mb-6 space-y-5 max-w-md">
                    <div className={`flex justify-between items-end border-b border-gray-700 pb-1 mb-2`} style={{ color: accentColor }}>
                        <span className="text-[10px] font-mono tracking-widest uppercase">PROFICIENCY METRICS</span>
