                {/* Stats Footer (Integrated) - FIXED AT BOTTOM */}
                <div className="mt-auto grid grid-cols-2 gap-x-12 gap-y-4 max-w-md border-t-2 border-white/10 pt-6">
                    <StatRow label="POWER" value={selectedItem.stats.damage} color={accentColor} />
                    <StatRow label="SPEED" value={selectedItem.stats.fireRate} color={accentColor} />
