                                        <div className="w-48 space-y-2">
                                            <div className="h-1.5 w-full bg-white/10 overflow-hidden">
                                                <div className="h-full bg-[#00F0FF]" style={{ width: `${weapon.stats.damage}%` }} />
                                            </div>
                                            <div className="h-1.5 w-full bg-white/10 overflow-hidden">
                                                <div className="h-full bg-[#00F0FF] opacity-60" style={{ width: `${weapon.stats.accuracy}%` }} />
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                </div>
            )}
        </div>
    );
};

