import React, { useMemo, useState, useRef } from 'react';
import { StackItem, WeaponConfig, ViewMode, ItemCategory } from '../types';
import { STACK_DATABASE, WEAPONS_DATABASE } from '../data';
import { Icons } from '../assets/Icons';
import { CategoryTab } from './CategoryTab';
import { SkillIcons } from '../assets/SkillIcons';

interface InventoryGridProps {
    viewMode: ViewMode;
    activeCategory: ItemCategory;
    onCategoryChange: (cat: ItemCategory) => void;
    selectedItem: StackItem | WeaponConfig;
    onSelect: (item: any) => void;
    onHover: (item: any | null) => void;
}

export const InventoryGrid: React.FC<InventoryGridProps> = ({ 
    viewMode, 
    activeCategory, 
    onCategoryChange, 
    selectedItem, 
    onSelect,
    onHover
}) => {
    const weaponBarClip = 'polygon(0 0, 98% 0, 100% 40%, 100% 100%, 2% 100%, 0 60%)';
    const [quickViewId, setQuickViewId] = useState<string | null>(null);
    const quickViewTimerRef = useRef<number | null>(null);

    const themeColor = viewMode === 'WEAPONS' ? '#00F0FF' : '#F2D019';

    const filteredResources = useMemo(() => {
        if (activeCategory === 'ALL') return STACK_DATABASE;
        return STACK_DATABASE.filter(item => item.category === activeCategory);
    }, [activeCategory]);

    const getIconComponent = (item: any) => {
        if (item.iconKey && SkillIcons[item.iconKey]) return SkillIcons[item.iconKey];
        if (SkillIcons[item.id]) return SkillIcons[item.id];
        return null;
    };

    const handleMouseEnter = (item: any) => {
        onHover(item);
        if (quickViewTimerRef.current) window.clearTimeout(quickViewTimerRef.current);
        quickViewTimerRef.current = window.setTimeout(() => {
            setQuickViewId(item.id);
        }, 1200); 
    };

    const handleMouseLeave = () => {
        onHover(null);
        setQuickViewId(null);
        if (quickViewTimerRef.current) {
            window.clearTimeout(quickViewTimerRef.current);
            quickViewTimerRef.current = null;
        }
    };

    return (
        <div className="w-full h-full flex flex-col relative min-h-0">
            {viewMode === 'RESOURCES' ? (
                <>
                    {/* Console-style Tabs Bar - Optimized Space */}
                    <div className="flex w-full border-b border-white/10 z-10 shrink-0 bg-[#080808] h-14 overflow-hidden">
                        <CategoryTab label="TODO" icon={<Icons.All className="w-4 h-4" />} active={activeCategory === 'ALL'} onClick={() => onCategoryChange('ALL')} color="#F2D019" isFirst />
                        <CategoryTab label="GRÁFICO" icon={<Icons.Graphic className="w-4 h-4" />} active={activeCategory === 'GRAPHIC'} onClick={() => onCategoryChange('GRAPHIC')} color="#f472b6" />
                        <CategoryTab label="UI/UX" icon={<Icons.UIUX className="w-4 h-4" />} active={activeCategory === 'UI_UX'} onClick={() => onCategoryChange('UI_UX')} color="#c084fc" />
                        <CategoryTab label="JUEGOS" icon={<Icons.Game className="w-4 h-4" />} active={activeCategory === 'GAME'} onClick={() => onCategoryChange('GAME')} color="#fb923c" />
                        <CategoryTab label="IA" icon={<Icons.AI className="w-4 h-4" />} active={activeCategory === 'AI'} onClick={() => onCategoryChange('AI')} color="#38bdf8" isLast />
                    </div>

                    <div className="flex-grow overflow-y-auto p-6 md:p-8 sci-fi-scroll relative bg-[#050505]">
                        <div className="grid grid-cols-3 sm:grid-cols-4 md:grid-cols-6 gap-4 content-start pb-4">
                            {filteredResources.map((item) => {
                                const isSelected = selectedItem.id === item.id;
                                const isQuickView = quickViewId === item.id;
                                const ToolIcon = getIconComponent(item);

                                return (
                                    <div 
                                        key={item.id} 
                                        onClick={() => onSelect(item)} 
                                        onMouseEnter={() => handleMouseEnter(item)} 
                                        onMouseLeave={handleMouseLeave} 
                                        className={`
                                            relative cursor-pointer aspect-square flex items-center justify-center rounded-lg 
                                            transition-all duration-300 group overflow-hidden
                                            ${isSelected 
                                                ? 'z-20 scale-110 border-4 border-white bg-black shadow-[0_0_30px_rgba(255,255,255,0.2)]' 
                                                : 'bg-[#111] border border-[#222] hover:bg-[#1a1a1a] hover:border-[#444] opacity-90'
                                            }
                                        `}
                                    >
                                        <div className="relative w-full h-full flex items-center justify-center p-2">
                                            <div className={`w-[60%] h-[60%] flex items-center justify-center transition-all duration-500 ${isQuickView ? 'opacity-5 scale-75' : 'opacity-100'}`}>
                                                {ToolIcon ? <ToolIcon className="w-full h-full" /> : <div className="w-4 h-4 bg-gray-600 rounded-sm" />}
                                            </div>

                                            <div className={`absolute inset-0 flex flex-col items-center justify-center p-2 transition-all duration-500 ${isQuickView ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-4 pointer-events-none'}`}>
                                                <div className="w-full space-y-1">
                                                    <div className="h-1 w-full bg-white/10 overflow-hidden"><div className="h-full" style={{ width: `${item.stats.damage}%`, backgroundColor: themeColor }} /></div>
                                                    <div className="h-1 w-full bg-white/10 overflow-hidden"><div className="h-full" style={{ width: `${item.stats.fireRate}%`, backgroundColor: themeColor, opacity: 0.5 }} /></div>
                                                </div>
                                                <span className="mt-2 font-mono text-[8px] text-white/40">LVL {item.level}</span>
                                            </div>
                                        </div>
                                    </div>
                                );
                            })}
                        </div>
                    </div>
                </>
            ) : (
                <div className="flex-grow p-4 md:p-6 overflow-y-auto sci-fi-scroll bg-[#050505]">
                    <div className="flex flex-col gap-3">
                        {WEAPONS_DATABASE.map((weapon) => {
                            const isSelected = selectedItem.id === weapon.id;
                            const isQuickView = quickViewId === weapon.id;
                            return (
                                <div 
                                    key={weapon.id} 
                                    onClick={() => onSelect(weapon)} 
                                    onMouseEnter={() => handleMouseEnter(weapon)} 
                                    onMouseLeave={handleMouseLeave}
                                    className={`
                                        relative h-24 w-full cursor-pointer flex items-center px-8 justify-between 
                                        transition-all duration-200 group overflow-hidden
                                        ${isSelected 
                                            ? 'bg-[#111] translate-x-2 border-4 border-white shadow-[0_0_30px_rgba(255,255,255,0.2)]' 
                                            : 'bg-[#0a0a0a] border-l-4 border-[#333] hover:bg-[#111] hover:border-white/50'
                                        }
                                    `}
                                    style={{ clipPath: weaponBarClip }}
                                >
                                    <div className="flex flex-col z-10">
                                        <span className={`font-['Teko'] text-3xl font-bold uppercase leading-none ${isSelected ? 'text-white' : 'text-gray-500'}`}>
                                            {weapon.name}
                                        </span>
                                        <span className={`font-mono text-[10px] ${isSelected ? 'text-[#00F0FF]' : 'text-gray-600'}`}>
                                            {weapon.subtitle}
                                        </span>
                                    </div>
                                    <div className="hidden sm:flex gap-2">
                                        {weapon.components.slice(0, 3).map(cid => (
                                            <div key={cid} className="w-8 h-8 p-1 flex items-center justify-center bg-black/50 rounded-full border border-white/10">
                                                {SkillIcons[cid] ? React.createElement(SkillIcons[cid], { className: "w-full h-full" }) : <div className="w-full h-full bg-gray-800 rounded-full" />}
                                            </div>
                                        ))}
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                </div>
            )}
        </div>
    );
};

