    score: number;
    icon: string;
    description: string;
    stats: ItemStats;
}

export interface WeaponConfig {
    id: string;
    name: string;
    subtitle: string;
    image: string;
    description: string;
    components: string[];
    stats: ItemStats;
    rarity: string; // Added for unified UI
