export interface ExtendedStackItem extends StackItem {
    iconKey?: string;
}

const mapCategory = (userCat: string): ItemCategory => {
    if (userCat.startsWith('AI')) return 'AI';
    if (userCat === '3D') return 'GAME';
    if (userCat === 'Game') return 'GAME';
    if (userCat === 'UI') return 'UI_UX';
    if (userCat === 'Video') return 'GRAPHIC'; 
    if (userCat === '2D') return 'GRAPHIC';
    return 'ALL';
};

const generateStats = (name: string) => {
    const seed = name.length;
    return {
        damage: 70 + (seed % 25),    // CAOS
        fireRate: 65 + (seed % 30),  // EFICIENCIA
        accuracy: 80 + (seed % 15),  // PRECISIÓN
        handling: 75 + (seed % 20)   // CREATIVIDAD
    };
};

