import React, { useState, useEffect, useRef } from 'react';
import { sfx } from '../../utils/SoundManager';
import { STACK_DATABASE, WEAPONS_DATABASE } from './data';
import { ViewMode, ItemCategory } from './types';
import { Icons } from './assets/Icons';

// Subcomponents
import { InventoryGrid } from './components/InventoryGrid';
import { InspectorPanel } from './components/InspectorPanel';

interface StackScreenProps {
    onClose: () => void;
}

export const StackScreen: React.FC<StackScreenProps> = ({ onClose }) => {
    const [viewMode, setViewMode] = useState<ViewMode>('RESOURCES');
    const [activeCategory, setActiveCategory] = useState<ItemCategory>('ALL');
    const [selectedItem, setSelectedItem] = useState<any>(STACK_DATABASE[0]);
    const [previewItem, setPreviewItem] = useState<any>(null);
    const [isClosing, setIsClosing] = useState(false);
    const [animateCard, setAnimateCard] = useState(false);

    const hoverTimerRef = useRef<number | null>(null);

    const themeColor = viewMode === 'WEAPONS' ? '#00F0FF' : '#F2D019';
    const themeText = viewMode === 'WEAPONS' ? 'text-[#00F0FF]' : 'text-[#F2D019]';

    useEffect(() => {
        sfx.play('EQUIP');
        return () => {
            if (hoverTimerRef.current) window.clearTimeout(hoverTimerRef.current);
        };
    }, []);

    const handleClose = () => {
        setIsClosing(true);
        sfx.play('CLICK');
        setTimeout(onClose, 300); 
    };

    const handleSelect = (item: any) => {
        if (item.id === selectedItem.id) return;
        if (hoverTimerRef.current) window.clearTimeout(hoverTimerRef.current);

        sfx.play('EQUIP');
        setSelectedItem(item);
        setPreviewItem(null); 
        setAnimateCard(true);
        setTimeout(() => setAnimateCard(false), 300);
    };

    const handleHover = (item: any | null) => {
        if (hoverTimerRef.current) {
            window.clearTimeout(hoverTimerRef.current);
            hoverTimerRef.current = null;
        }

        if (item) {
            if (item.id !== selectedItem.id) {
                hoverTimerRef.current = window.setTimeout(() => {
                    setPreviewItem(item);
                    sfx.play('HOVER');
                }, 500); 
            }
        } else {
            setPreviewItem(null);
        }
    };

    const handleModeSwitch = (mode: ViewMode) => {
        if (viewMode === mode) return;
        sfx.play(mode === 'RESOURCES' ? 'CLICK' : 'EQUIP');
        setViewMode(mode);
        const defaultItem = mode === 'WEAPONS' ? WEAPONS_DATABASE[0] : STACK_DATABASE[0];
        setSelectedItem(defaultItem);
        setPreviewItem(null);
    };

    const itemToDisplay = previewItem || selectedItem;

    return (
        <div className={`
            fixed inset-0 z-[200] flex flex-col items-center
            bg-[#050505] overflow-hidden select-none
            ${isClosing ? 'animate-out fade-out duration-300' : 'animate-stack-entry'}
        `}>

            <div className="absolute inset-0 pointer-events-none z-0 opacity-20 animate-bg-pan" 
                 style={{ 
                     backgroundImage: 'radial-gradient(#555 3px, transparent 3px)', 
                     backgroundSize: '40px 40px' 
                 }} 
            />

            {/* HEADER AREA - Fixed Alignment using Clip Paths instead of Skew hacks */}
            <div className="relative w-full max-w-[1800px] mt-6 mb-4 z-50 flex flex-col md:flex-row items-center justify-between px-6 gap-0 shrink-0 animate-fade-up delay-100">

                <div className="flex items-stretch h-14 bg-white/5 border border-white/10 p-0.5 rounded-sm">
                    {/* Botón SALIR */}
                    <button 
                        onClick={handleClose} 
                        className="relative flex items-center justify-center px-10 h-full bg-[#ef4444] text-black hover:bg-white transition-all z-30 group"
                        style={{ clipPath: 'polygon(0 0, 100% 0, 85% 100%, 0 100%)' }}
                    >
                        <div className="flex items-center gap-2 pr-3">
                            <Icons.Close className="w-5 h-5 transition-transform group-hover:rotate-90" />
                            <span className="font-['Teko'] text-2xl font-bold tracking-widest pt-1">SALIR</span>
                        </div>
                    </button>

                    {/* Botón SOFTWARE - No Skew on container to keep it "Derecho" */}
                    <button onClick={() => handleModeSwitch('RESOURCES')} 
                        className={`
                            relative flex items-center justify-center px-14 h-full transition-all duration-300
                            ${viewMode === 'RESOURCES' 
                                ? 'bg-[#F2D019] text-black z-20 shadow-[0_5px_15px_rgba(242,208,25,0.4)]' 
                                : 'bg-[#18181b] text-gray-500 hover:text-white z-10'
                            }
                        `}
                        style={{ clipPath: 'polygon(15% 0, 100% 0, 85% 100%, 0% 100%)', marginLeft: '-15px' }}
                    >
                        <span className="font-['Teko'] text-2xl font-bold tracking-widest pt-1">SOFTWARE</span>
                    </button>

                    {/* Botón ARMAS */}
                    <button onClick={() => handleModeSwitch('WEAPONS')} 
                        className={`
                            relative flex items-center justify-center px-14 h-full transition-all duration-300
                            ${viewMode === 'WEAPONS' 
                                ? 'bg-[#3b82f6] text-white z-20 shadow-[0_5px_15px_rgba(59,130,246,0.4)]' 
                                : 'bg-[#18181b] text-gray-500 hover:text-white z-10'
                            }
                        `}
                        style={{ clipPath: 'polygon(15% 0, 100% 0, 100% 100%, 0% 100%)', marginLeft: '-15px' }}
                    >
                        <span className="font-['Teko'] text-2xl font-bold tracking-widest pt-1 pr-4">ARMAS</span>
                    </button>
                </div>

                <div className="flex flex-col items-end transform -skew-x-[10deg] border-r-4 border-white pr-4 self-end md:self-auto ml-auto">
                    <h1 className="font-['Teko'] text-5xl font-bold text-white leading-none tracking-wider italic uppercase">SKILLS_INVENTORY</h1>
                    <span className={`font-mono text-[10px] tracking-[0.3em] font-bold ${themeText}`}>
                        {viewMode === 'WEAPONS' ? 'ARSENAL_LOADOUT' : 'SOFTWARE_INVENTORY'}
                    </span>
                </div>
            </div>

            {/* MAIN CONTENT AREA - Total Floating HUD Experience */}
            <div className="relative w-full max-w-[1800px] flex-grow flex flex-col lg:flex-row gap-8 p-6 z-10 overflow-hidden h-full pb-8">
                {/* LEFT: Grid on blurred glass */}
                <div className="w-full lg:w-[50%] h-full flex flex-col relative rounded-xl overflow-hidden bg-black/10 border border-white/5 backdrop-blur-[4px] animate-fade-up delay-200">
                    <InventoryGrid 
                        viewMode={viewMode} 
                        activeCategory={activeCategory} 
                        onCategoryChange={setActiveCategory} 
                        selectedItem={selectedItem} 
                        onSelect={handleSelect} 
                        onHover={handleHover} 
                    />
                </div>

                {/* RIGHT: Floating HUD (No Container) */}
                <div className="w-full lg:w-[50%] h-full flex flex-col relative animate-fade-up delay-300">
                    <InspectorPanel 
                        selectedItem={itemToDisplay} 
                        animateCard={animateCard} 
                        themeColor={themeColor}
                    />
                </div>
            </div>
        </div>
    );
};

