import React, { useState, useEffect, useRef } from 'react';
import { sfx } from '../../utils/SoundManager';
import { STACK_DATABASE, WEAPONS_DATABASE } from './data';
import { ViewMode, ItemCategory } from './types';
import { Icons } from './assets/Icons';

// Subcomponents
import { InventoryGrid } from './components/InventoryGrid';
import { InspectorPanel } from './components/InspectorPanel';

interface StackScreenProps {
    onClose: () => void;
}

export const StackScreen: React.FC<StackScreenProps> = ({ onClose }) => {
    const [viewMode, setViewMode] = useState<ViewMode>('RESOURCES');
    const [activeCategory, setActiveCategory] = useState<ItemCategory>('ALL');
    const [selectedItem, setSelectedItem] = useState<any>(STACK_DATABASE[0]);
    const [previewItem, setPreviewItem] = useState<any>(null);
    const [isClosing, setIsClosing] = useState(false);
    const [animateCard, setAnimateCard] = useState(false);

    const hoverTimerRef = useRef<number | null>(null);

    const themeColor = viewMode === 'WEAPONS' ? '#00F0FF' : '#F2D019';
    const themeText = viewMode === 'WEAPONS' ? 'text-[#00F0FF]' : 'text-[#F2D019]';

    useEffect(() => {
        // Sonido de apertura silenciado por feedback
        return () => {
            if (hoverTimerRef.current) window.clearTimeout(hoverTimerRef.current);
        };
    }, []);

    const handleClose = () => {
        setIsClosing(true);
        sfx.play('CLICK');
        setTimeout(onClose, 300); 
    };

    const handleSelect = (item: any) => {
        if (item.id === selectedItem.id) return;
        if (hoverTimerRef.current) window.clearTimeout(hoverTimerRef.current);

        sfx.play('CLICK');
        setSelectedItem(item);
        setPreviewItem(null); 
        setAnimateCard(true);
        setTimeout(() => setAnimateCard(false), 300);
    };

    const handleHover = (item: any | null) => {
        if (hoverTimerRef.current) {
            window.clearTimeout(hoverTimerRef.current);
            hoverTimerRef.current = null;
        }

        if (item) {
            if (item.id !== selectedItem.id) {
                hoverTimerRef.current = window.setTimeout(() => {
                    setPreviewItem(item);
                    sfx.play('HOVER');
                }, 500); 
            }
        } else {
            setPreviewItem(null);
        }
    };

    const handleModeSwitch = (mode: ViewMode) => {
        if (viewMode === mode) return;
        sfx.play('CLICK');
        setViewMode(mode);
        const defaultItem = mode === 'WEAPONS' ? WEAPONS_DATABASE[0] : STACK_DATABASE[0];
        setSelectedItem(defaultItem);
        setPreviewItem(null);
    };

    const itemToDisplay = previewItem || selectedItem;

    return (
        <div className={`
            fixed inset-0 z-[200] flex flex-col items-center
            bg-[#050505] overflow-hidden select-none
            ${isClosing ? 'animate-out fade-out duration-300' : 'animate-stack-entry'}
        `}>

            <div className="absolute inset-0 pointer-events-none z-0 opacity-20 animate-bg-pan" 
                 style={{ 
                     backgroundImage: 'radial-gradient(#555 3px, transparent 3px)', 
                     backgroundSize: '40px 40px' 
                 }} 
            />

            {/* HEADER AREA - Perfect Coupled Buttons */}
            <div className="relative w-full max-w-[1800px] mt-8 mb-6 z-50 flex flex-col md:flex-row items-center justify-between px-10 gap-0 shrink-0 animate-fade-up delay-100">

                {/* UNIFIED TAB SYSTEM (SKEWED GROUP) */}
                <div className="flex items-stretch h-14 bg-white/5 border border-white/10 p-0.5 rounded-sm overflow-visible">

                    {/* Botón SALIR - Inclinación integrada */}
                    <button 
                        onClick={handleClose} 
                        className="relative flex items-center justify-center px-12 h-full bg-[#ef4444] text-black hover:bg-white transition-all z-30 group"
                        style={{ transform: 'skewX(-15deg)', marginLeft: '-15px' }}
                    >
                        <div className="flex items-center gap-3" style={{ transform: 'skewX(15deg)' }}>
                            <Icons.Close className="w-6 h-6 transition-transform group-hover:rotate-90" />
                            <span className="font-['Teko'] text-3xl font-bold tracking-widest pt-1">SALIR</span>
                        </div>
                    </button>

                    {/* Botón SOFTWARE - Acoplamiento perfecto con el anterior */}
                    <button onClick={() => handleModeSwitch('RESOURCES')} 
                        className={`
                            relative flex items-center justify-center px-16 h-full transition-all duration-300 border-x border-black/20
                            ${viewMode === 'RESOURCES' 
                                ? 'bg-[#F2D019] text-black z-20 shadow-[0_0_25px_rgba(242,208,25,0.4)]' 
                                : 'bg-[#151515] text-gray-500 hover:text-white z-10'
                            }
                        `}
                        style={{ transform: 'skewX(-15deg)', marginLeft: '-1px' }}
                    >
                        <span className="font-['Teko'] text-3xl font-bold tracking-widest pt-1" style={{ transform: 'skewX(15deg)' }}>SOFTWARE</span>
                    </button>

                    {/* Botón ARMAS - Acoplamiento perfecto con el anterior */}
                    <button onClick={() => handleModeSwitch('WEAPONS')} 
                        className={`
                            relative flex items-center justify-center px-16 h-full transition-all duration-300
                            ${viewMode === 'WEAPONS' 
                                ? 'bg-[#00F0FF] text-black z-20 shadow-[0_0_25px_rgba(0,240,255,0.4)]' 
                                : 'bg-[#151515] text-gray-500 hover:text-white z-10'
                            }
                        `}
                        style={{ transform: 'skewX(-15deg)', marginLeft: '-1px', marginRight: '-15px' }}
                    >
                        <span className="font-['Teko'] text-3xl font-bold tracking-widest pt-1 pr-4" style={{ transform: 'skewX(15deg)' }}>ARMAS</span>
                    </button>
                </div>

                <div className="flex flex-col items-end transform -skew-x-[10deg] border-r-4 border-white pr-4 self-end md:self-auto ml-auto">
                    <h1 className="font-['Teko'] text-6xl font-bold text-white leading-none tracking-wider italic uppercase">SKILLS_INVENTORY</h1>
                    <span className={`font-mono text-[10px] tracking-[0.4em] font-bold ${themeText}`}>
                        {viewMode === 'WEAPONS' ? 'ARSENAL_LOADOUT' : 'SOFTWARE_INVENTORY'}
                    </span>
                </div>
            </div>

            {/* MAIN CONTENT AREA */}
            <div className="relative w-full max-w-[1800px] flex-grow flex flex-col lg:flex-row gap-12 p-8 z-10 overflow-hidden h-full pb-10">
                {/* LEFT: Grid */}
                <div className="w-full lg:w-[48%] h-full flex flex-col relative rounded-xl overflow-hidden bg-black/25 border border-white/5 backdrop-blur-[4px] animate-fade-up delay-200 shadow-2xl">
                    <InventoryGrid 
                        viewMode={viewMode} 
                        activeCategory={activeCategory} 
                        onCategoryChange={setActiveCategory} 
                        selectedItem={selectedItem} 
                        onSelect={handleSelect} 
                        onHover={handleHover} 
                    />
                </div>

                {/* RIGHT: Floating Inspector */}
                <div className="w-full lg:w-[52%] h-full flex flex-col relative animate-fade-up delay-300">
                    <InspectorPanel 
                        selectedItem={itemToDisplay} 
                        animateCard={animateCard} 
                        themeColor={themeColor}
                    />
                </div>
            </div>
        </div>
    );
};

