const mapCategory = (userCat: string): ItemCategory => {
    const uc = userCat.toUpperCase();
    if (uc === 'AI') return 'AI';
    if (uc === '3D' || uc === 'GAME') return 'GAME';
    if (uc === 'UI' || uc === 'UI_UX') return 'UI_UX';
    if (uc === 'VIDEO' || uc === 'GRAPHIC' || uc === '2D') return 'GRAPHIC';
    return 'ALL';
};

const generateStats = (name: string) => {
    const seed = name.length;
    return {
        damage: 70 + (seed % 25),    // CAOS
        fireRate: 65 + (seed % 30),  // EFICIENCIA
        accuracy: 80 + (seed % 15),  // PRECISIÓN
        handling: 75 + (seed % 20)   // CREATIVIDAD
    };
};

