export const InventoryGrid: React.FC<InventoryGridProps> = ({ 
    viewMode, 
    activeCategory, 
    onCategoryChange, 
    selectedItem, 
    onSelect,
    onHover
}) => {
    const weaponBarClip = 'polygon(0 0, 98% 0, 100% 40%, 100% 100%, 2% 100%, 0 60%)';
    const [quickViewId, setQuickViewId] = useState<string | null>(null);
    const quickViewTimerRef = useRef<number | null>(null);

    const filteredResources = useMemo(() => {
        if (activeCategory === 'ALL') return STACK_DATABASE;
        return STACK_DATABASE.filter(item => item.category === activeCategory);
    }, [activeCategory]);

    const getIconComponent = (item: any) => {
        if (item.iconKey && SkillIcons[item.iconKey]) return SkillIcons[item.iconKey];
        if (SkillIcons[item.id]) return SkillIcons[item.id];
        return null;
    };

    const handleMouseEnter = (item: any) => {
        onHover(item);
        if (quickViewTimerRef.current) window.clearTimeout(quickViewTimerRef.current);
        quickViewTimerRef.current = window.setTimeout(() => {
            setQuickViewId(item.id);
        }, 1200); 
    };

    const handleMouseLeave = () => {
        onHover(null);
        setQuickViewId(null);
        if (quickViewTimerRef.current) {
            window.clearTimeout(quickViewTimerRef.current);
            quickViewTimerRef.current = null;
        }
    };

    return (
        <div className="w-full h-full flex flex-col relative min-h-0 bg-[#050505]">
            {viewMode === 'RESOURCES' ? (
                <>
                    {/* TACTICAL TABS BAR - No bottom border, spaced out */}
                    <div className="flex w-full z-10 shrink-0 h-16 items-center px-4 pt-4 pb-2 gap-2 bg-gradient-to-b from-[#111] to-transparent">
                        <CategoryTab label="TODO" icon={<Icons.All className="w-4 h-4" />} active={activeCategory === 'ALL'} onClick={() => onCategoryChange('ALL')} color="#F2D019" />
