    iconKey?: string;
}

const mapCategory = (userCat: string): ItemCategory => {
    const uc = userCat.toUpperCase();
    if (uc === 'AI') return 'AI';
    if (uc === '3D' || uc === 'GAME') return 'GAME';
    if (uc === 'UI' || uc === 'UI_UX') return 'UI_UX';
    if (uc === 'VIDEO' || uc === 'GRAPHIC' || uc === '2D') return 'GRAPHIC';
    return 'ALL';
};

// Generador de stats aleatorios pero coherentes
const generateStats = (seed: number) => {
    return {
        knowledge: 70 + (seed % 30),    
        versatility: 60 + (seed % 40), 
        interface: 80 + (seed % 20),  
        learning: 50 + (seed % 50)   
    };
};

