        {active && (
            <div 
                className="absolute inset-0 opacity-30 pointer-events-none"
                style={{ 
                    backgroundImage: 'linear-gradient(0deg, transparent 50%, rgba(0,0,0,0.5) 50%)',
                    backgroundSize: '100% 4px'
                }} 
            />
        )}

        {/* Content Layer */}
        <div className={`
            relative z-10 flex items-center gap-2 px-4 
            ${active ? 'text-black' : 'text-gray-400 group-hover:text-white'}
        `}>
            <div className={`transition-transform duration-300 ${active ? 'scale-110' : ''}`}>
                {icon}
            </div>

            <span className="font-['Teko'] text-xl tracking-widest leading-none pt-1 uppercase font-bold">
                {label}
            </span>
        </div>

        {/* Decorative Corner Bits (HUD Style) */}
        {!active && (
            <>
                <div className="absolute top-0 right-0 w-2 h-2 border-t border-r border-gray-500/50" />
                <div className="absolute bottom-0 left-0 w-2 h-2 border-b border-l border-gray-500/50" />
            </>
        )}
    </button>
);

import React, { useMemo, useState, useRef } from 'react';
import { StackItem, WeaponConfig, ViewMode, ItemCategory } from '../types';
import { STACK_DATABASE, WEAPONS_DATABASE } from '../data';
import { Icons } from '../assets/Icons';
import { CategoryTab } from './CategoryTab';
import { SkillIcons } from '../assets/SkillIcons';

interface InventoryGridProps {
    viewMode: ViewMode;
    activeCategory: ItemCategory;
    onCategoryChange: (cat: ItemCategory) => void;
    selectedItem: StackItem | WeaponConfig;
    onSelect: (item: any) => void;
    onHover: (item: any | null) => void;
}

// RARITY VISUAL SYSTEM
const RARITY_STYLES = {
    common: {
        border: 'border-gray-600',
        glow: 'shadow-none',
        bg: 'bg-[#111]'
    },
    rare: {
        border: 'border-blue-500',
        glow: 'shadow-[0_0_10px_rgba(59,130,246,0.3)]',
        bg: 'bg-blue-900/10'
    },
    epic: {
        border: 'border-purple-500',
        glow: 'shadow-[0_0_15px_rgba(168,85,247,0.4)]',
        bg: 'bg-purple-900/10'
    },
    legendary: {
        border: 'border-amber-400',
        glow: 'shadow-[0_0_20px_rgba(251,191,36,0.5)]',
        bg: 'bg-amber-900/10'
    },
    mystic: {
        border: 'border-pink-500',
        glow: 'shadow-[0_0_25px_rgba(236,72,153,0.6)]',
        bg: 'bg-pink-900/20'
    }
};

export const InventoryGrid: React.FC<InventoryGridProps> = ({ 
    viewMode, 
    activeCategory, 
    onCategoryChange, 
    selectedItem, 
    onSelect,
    onHover
}) => {
    const weaponBarClip = 'polygon(0 0, 98% 0, 100% 40%, 100% 100%, 2% 100%, 0 60%)';
    const [quickViewId, setQuickViewId] = useState<string | null>(null);
    const quickViewTimerRef = useRef<number | null>(null);

    const filteredResources = useMemo(() => {
        if (activeCategory === 'ALL') return STACK_DATABASE;
        return STACK_DATABASE.filter(item => item.category === activeCategory);
    }, [activeCategory]);

    const getIconComponent = (item: any) => {
        if (item.iconKey && SkillIcons[item.iconKey]) return SkillIcons[item.iconKey];
        if (SkillIcons[item.id]) return SkillIcons[item.id];
        return null;
    };

    const handleMouseEnter = (item: any) => {
        onHover(item);
        if (quickViewTimerRef.current) window.clearTimeout(quickViewTimerRef.current);
        quickViewTimerRef.current = window.setTimeout(() => {
            setQuickViewId(item.id);
        }, 1200); 
    };

    const handleMouseLeave = () => {
        onHover(null);
        setQuickViewId(null);
        if (quickViewTimerRef.current) {
            window.clearTimeout(quickViewTimerRef.current);
            quickViewTimerRef.current = null;
        }
    };

    return (
        <div className="w-full h-full flex flex-col relative min-h-0 bg-[#050505]">
            {viewMode === 'RESOURCES' ? (
                <>
                    {/* TACTICAL TABS BAR - No bottom border, spaced out */}
                    <div className="flex w-full z-10 shrink-0 h-16 items-center px-4 pt-4 pb-2 gap-2 bg-gradient-to-b from-[#111] to-transparent">
                        <CategoryTab label="TODO" icon={<Icons.All className="w-4 h-4" />} active={activeCategory === 'ALL'} onClick={() => onCategoryChange('ALL')} color="#F2D019" />
                        <CategoryTab label="GRÁFICO" icon={<Icons.Graphic className="w-4 h-4" />} active={activeCategory === 'GRAPHIC'} onClick={() => onCategoryChange('GRAPHIC')} color="#f472b6" />
                        <CategoryTab label="UI/UX" icon={<Icons.UIUX className="w-4 h-4" />} active={activeCategory === 'UI_UX'} onClick={() => onCategoryChange('UI_UX')} color="#c084fc" />
                        <CategoryTab label="JUEGOS" icon={<Icons.Game className="w-4 h-4" />} active={activeCategory === 'GAME'} onClick={() => onCategoryChange('GAME')} color="#fb923c" />
                        <CategoryTab label="IA" icon={<Icons.AI className="w-4 h-4" />} active={activeCategory === 'AI'} onClick={() => onCategoryChange('AI')} color="#38bdf8" />
                    </div>

                    <div className="flex-grow overflow-y-auto p-6 md:p-8 sci-fi-scroll relative">
                        <div className="grid grid-cols-3 sm:grid-cols-4 md:grid-cols-6 gap-5 content-start pb-4">
                            {filteredResources.map((item) => {
                                const isSelected = selectedItem.id === item.id;
                                const isQuickView = quickViewId === item.id;
                                const ToolIcon = getIconComponent(item);

                                // Rarity Logic
                                const rarity = item.rarity || 'common';
                                const styles = RARITY_STYLES[rarity] || RARITY_STYLES.common;

                                return (
                                    <div 
                                        key={item.id} 
                                        onClick={() => onSelect(item)} 
                                        onMouseEnter={() => handleMouseEnter(item)} 
                                        onMouseLeave={handleMouseLeave} 
                                        className={`
                                            relative cursor-pointer aspect-square flex items-center justify-center 
                                            transition-all duration-300 group overflow-hidden
                                            border-2 ${styles.bg}
                                            ${isSelected 
                                                ? `z-20 scale-110 ${styles.border} ${styles.glow} bg-black ring-1 ring-white/50` 
                                                : `border-[#222] hover:border-gray-500 hover:scale-105 opacity-90`
                                            }
                                        `}
                                        style={{
                                            clipPath: 'polygon(10% 0, 100% 0, 100% 90%, 90% 100%, 0 100%, 0 10%)' // Chamfered Icon Box
                                        }}
                                    >
                                        {/* Rarity Corner Marker */}
                                        <div className={`absolute top-0 right-0 w-3 h-3 ${isSelected ? styles.bg.replace('/10', '') : 'bg-[#333]'}`} style={{ clipPath: 'polygon(0 0, 100% 0, 100% 100%)'}} />

                                        <div className="relative w-full h-full flex items-center justify-center p-2">
                                            <div className={`w-[60%] h-[60%] flex items-center justify-center transition-all duration-500 ${isQuickView ? 'opacity-5 scale-75' : 'opacity-100'}`}>
                                                {ToolIcon ? <ToolIcon className="w-full h-full" /> : <div className="w-4 h-4 bg-gray-600 rounded-sm" />}
                                            </div>

                                            {/* Quick Stats Overlay on Hover */}
                                            <div className={`absolute inset-0 flex flex-col items-center justify-center p-2 transition-all duration-500 ${isQuickView ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-4 pointer-events-none'}`}>
                                                <div className="w-full space-y-1">
                                                    {/* Simple bar visualizer */}
                                                    <div className="h-1 w-full bg-white/10"><div className="h-full bg-white" style={{ width: `${item.stats.knowledge}%` }} /></div>
                                                    <div className="h-1 w-full bg-white/10"><div className="h-full bg-white/50" style={{ width: `${item.stats.interface}%` }} /></div>
                                                </div>
                                                <span className={`mt-2 font-mono text-[8px] uppercase tracking-widest ${isSelected ? 'text-white' : 'text-gray-400'}`}>
                                                    {item.rarity}
                                                </span>
                                            </div>
                                        </div>
                                    </div>
                                );
                            })}
                        </div>
                    </div>
                </>
            ) : (
                <div className="flex-grow p-4 md:p-6 overflow-y-auto sci-fi-scroll">
                    <div className="flex flex-col gap-3">
                        {WEAPONS_DATABASE.map((weapon) => {
                            const isSelected = selectedItem.id === weapon.id;
                            // Weapon Rarity Mapping
                            const rarity = (weapon.rarity as keyof typeof RARITY_STYLES) || 'epic';
                            const styles = RARITY_STYLES[rarity];

                            return (
                                <div 
                                    key={weapon.id} 
                                    onClick={() => onSelect(weapon)} 
                                    onMouseEnter={() => handleMouseEnter(weapon)} 
                                    onMouseLeave={handleMouseLeave}
                                    className={`
                                        relative h-24 w-full cursor-pointer flex items-center px-8 justify-between 
                                        transition-all duration-200 group overflow-hidden border-l-4
                                        ${isSelected 
                                            ? `bg-[#111] translate-x-2 ${styles.border} ${styles.glow}` 
                                            : 'bg-[#0a0a0a] border-[#333] hover:bg-[#111] hover:border-white/50'
                                        }
                                    `}
                                    style={{ clipPath: weaponBarClip }}
                                >
                                    <div className="flex flex-col z-10">
                                        <span className={`font-['Teko'] text-3xl font-bold uppercase leading-none ${isSelected ? 'text-white' : 'text-gray-500'}`}>
                                            {weapon.name}
                                        </span>
                                        <div className="flex items-center gap-2">
                                            <span className={`text-[9px] uppercase px-1 rounded bg-white/10 ${isSelected ? 'text-[#00F0FF]' : 'text-gray-600'}`}>
                                                {weapon.rarity}
                                            </span>
                                            <span className="font-mono text-[10px] text-gray-500">
                                                {weapon.subtitle}
                                            </span>
                                        </div>
                                    </div>
                                    <div className="hidden sm:flex gap-2">
                                        {weapon.components.slice(0, 3).map(cid => (
                                            <div key={cid} className="w-8 h-8 p-1 flex items-center justify-center bg-black/50 rounded-full border border-white/10">
                                                {SkillIcons[cid] ? React.createElement(SkillIcons[cid], { className: "w-full h-full" }) : <div className="w-full h-full bg-gray-800 rounded-full" />}
                                            </div>
                                        ))}
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                </div>
            )}
        </div>
    );
};

import React from 'react';
import { StackItem, WeaponConfig, isWeapon } from '../types';
import { ExtendedStackItem } from '../data';
import { SkillIcons } from '../assets/SkillIcons';
import { Visualizer3D } from './3d/Visualizer3D';

interface InspectorPanelProps {
    selectedItem: StackItem | WeaponConfig;
    animateCard: boolean;
    themeColor?: string;
}

export const InspectorPanel: React.FC<InspectorPanelProps> = React.memo(({ selectedItem, animateCard, themeColor = '#F2D019' }) => {

    const accentColor = themeColor; 
    const extendedItem = !isWeapon(selectedItem) ? (selectedItem as ExtendedStackItem) : null;
    const IconComponent = extendedItem?.iconKey ? SkillIcons[extendedItem.iconKey] : null;
    const isEpic = selectedItem.rarity === 'epic' || selectedItem.rarity === 'legendary' || selectedItem.rarity === 'mystic';

    const has3D = ['3dsmax', 'blender', 'figma', 'xd', 'ae', 'premiere', 'ai', 'sub_painter', 'sub_designer', 'powershell', 'id', 'ps', 'affinity', 'audition'].includes(selectedItem.id);

    // DYNAMIC SCORE CALCULATION
    const stats = selectedItem.stats;
    const totalScore = stats.knowledge + stats.versatility + stats.interface + stats.learning;

    // Percentage for the circle (Total / Max 400) * 100
    const scorePercentage = (totalScore / 400) * 100;

    return (
        <div className={`
            w-full h-full flex flex-col relative transition-all duration-300
            ${animateCard ? 'opacity-50 scale-[0.98]' : 'opacity-100 scale-100'}
        `}>
            {/* 1. FLOATING HEADER HUD */}
            <div className="absolute top-0 left-0 right-0 z-20 flex justify-between items-start pointer-events-none">
                <div className="flex flex-col p-2">
                    <div className="flex items-center gap-4 mb-2">
                        <div className="h-[2px] w-16" style={{ backgroundColor: accentColor, boxShadow: `0 0 15px ${accentColor}` }} />
                        <span className="text-[11px] font-mono tracking-[0.5em] font-black uppercase" style={{ color: accentColor }}>
                            {isWeapon(selectedItem) ? 'ELITE_PROJECT_ARMAMENT' : `${selectedItem.manufacturer} // ARTIFACT`}
                        </span>
                    </div>
                    <h2 className="font-['Teko'] text-8xl font-bold uppercase leading-[0.7] text-white tracking-tighter drop-shadow-[0_10px_20px_rgba(0,0,0,0.8)]">
                        {selectedItem.name}
                    </h2>
                </div>

                {/* DYNAMIC SCORE CORE */}
                <div className="relative w-36 h-36 flex items-center justify-center pointer-events-auto">
                    <div className="absolute inset-4 rounded-full blur-2xl opacity-20 animate-pulse" style={{ backgroundColor: accentColor }} />

                    <svg className="w-full h-full transform -rotate-90 scale-90 overflow-visible">
                        {/* Outer Track */}
                        <circle cx="72" cy="72" r="62" stroke="white" strokeWidth="1" fill="transparent" opacity="0.05" />
                        {/* Score Track */}
                        <circle 
                            cx="72" cy="72" r="62" stroke="currentColor" strokeWidth="10" fill="transparent" 
                            strokeDasharray={389.5} strokeDashoffset={389.5 - (389.5 * scorePercentage / 100)}
                            strokeLinecap="butt"
                            className="transition-all duration-1000 ease-out"
                            style={{ color: accentColor, filter: `drop-shadow(0 0 18px ${accentColor})` }}
                        />
                        {/* Aiming Marks - Coordinated */}
                        {[...Array(12)].map((_, i) => (
                             <rect key={i} x="71" y="2" width="2" height="12" fill="white" opacity="0.4" transform={`rotate(${i * 30} 72 72)`} />
                        ))}
                    </svg>

                    <div className="absolute inset-0 flex flex-col items-center justify-center pt-2">
                        <span className="font-mono text-[10px] text-white/40 font-black tracking-[0.2em] leading-none mb-1">TOTAL_PWR</span>
                        <span className="font-['Teko'] text-7xl font-bold leading-none text-white drop-shadow-[0_0_15px_rgba(255,255,255,0.4)]">
                            {totalScore}
                        </span>
                    </div>
                </div>
            </div>

            {/* 2. CENTRAL FLOATING ASSET */}
            <div className="flex-grow flex items-center justify-center relative z-10 pt-16">
                <div className="absolute inset-0 flex items-center justify-center pointer-events-none overflow-hidden opacity-50">
                    <div className="w-[120%] h-[120%] bg-[radial-gradient(circle,rgba(255,255,255,0.03)_0%,transparent_70%)]" />
                    {isEpic && <div className="absolute w-[90%] h-[90%] bg-[radial-gradient(circle,rgba(242,208,25,0.06)_0%,transparent_65%)] animate-pulse" />}
                </div>

                <div className="w-full h-full max-h-[650px] flex items-center justify-center relative scale-125">
                    {has3D ? (
                        <div className="w-full h-full"><Visualizer3D itemId={selectedItem.id} /></div>
                    ) : isWeapon(selectedItem) ? (
                        <img src={selectedItem.image} alt={selectedItem.name} className="h-full w-auto object-contain drop-shadow-[0_50px_100px_rgba(0,0,0,0.9)] animate-float" />
                    ) : (
                        <div className="relative w-full h-full flex items-center justify-center">
                            {IconComponent ? (
                                <IconComponent className="w-[70%] h-[70%] object-contain drop-shadow-[0_0_80px_rgba(255,255,255,0.15)] animate-float" />
                            ) : (
                                <img src={selectedItem.icon} className="w-[60%] h-[60%] object-contain animate-float" alt="Icon" />
                            )}
                        </div>
                    )}
                </div>
            </div>

            {/* 3. FLOATING HUD DATA BLOCKS */}
            <div className="mt-auto flex flex-col md:flex-row gap-8 items-end pointer-events-none pb-6 px-4">

                {/* STATS HUD - Refactored */}
                <div className="flex flex-col gap-5 p-8 bg-black/30 border-l-4 border-white/20 backdrop-blur-[4px] w-full md:w-[45%]">
                    <div className="flex items-center gap-3 mb-1">
                        <div className="w-3 h-3 bg-white/20 rotate-45" />
                        <span className="text-[11px] font-mono text-white/50 tracking-[0.3em] font-bold">STATS</span>
                    </div>
                    <div className="space-y-5">
                        <AttributeBlock label="CONOCIMIENTO" value={selectedItem.stats.knowledge} color="#00F0FF" />
                        <AttributeBlock label="VERSATILIDAD" value={selectedItem.stats.versatility} color="#ef4444" />
                        <AttributeBlock label="INTERFACE" value={selectedItem.stats.interface} color="#22c55e" />
                        <AttributeBlock label="APRENDIZAJE" value={selectedItem.stats.learning} color="#F2D019" />
                    </div>
                </div>

                {/* DESCRIPTION HUD */}
                <div className="flex flex-col gap-4 p-8 bg-black/30 border-r-4 border-white/20 backdrop-blur-[4px] text-right w-full md:w-[55%]">
                    <div className="text-[10px] font-mono text-white/40 uppercase tracking-widest border-b border-white/10 pb-2 mb-2">MANIFEST_X_091</div>
                    <p className="font-['Roboto_Mono'] text-[13px] text-gray-200 leading-relaxed italic pr-6 border-r-2 border-white/10">
                        "{selectedItem.description}"
                    </p>
                    <div className="mt-4 flex justify-between items-end">
                         <div className="flex flex-col items-start pl-6 border-l-2 border-white/10">
                            <span className="text-[9px] font-mono text-white/30 uppercase tracking-tighter">CLASS TIER</span>
                            <span className={`font-['Teko'] text-5xl font-bold uppercase leading-none ${isEpic ? 'text-[#F2D019]' : 'text-white'}`}>
                                {selectedItem.rarity}
                            </span>
                        </div>
                        <div className="flex flex-col items-end">
                            <span className="text-[9px] font-mono text-white/30 uppercase tracking-tighter">SYNC_STATUS</span>
                            <span className="font-['Teko'] text-5xl font-bold text-white leading-none drop-shadow-[0_0_10px_rgba(255,255,255,0.3)]">
                                {scorePercentage >= 80 ? 'OPTIMAL' : 'STABLE'}
                            </span>
                        </div>
                    </div>
                </div>

            </div>
        </div>
    );
});

const AttributeBlock = ({ label, value, color }: { label: string, value: number, color: string }) => (
    <div className="flex flex-col gap-2">
        <div className="flex justify-between items-center px-1">
            <span className="text-[10px] font-mono text-white/70 font-black tracking-widest">{label}</span>
            <span className="text-[12px] font-mono font-bold" style={{ color }}>{value}%</span>
        </div>
        <div className="h-1.5 w-full bg-white/5 rounded-none overflow-hidden border border-white/10">
            <div className="h-full transition-all duration-1000 ease-out" style={{ width: `${value}%`, backgroundColor: color, boxShadow: `0 0 12px ${color}` }} />
        </div>
    </div>
);
